EMBED.domains.push({id:'repair',title:'Repair & circular stewardship',description:'Preserve the original Protocol repair engine; do not confuse cost savings with environmental benefit.'});
const ROUTES=[['home','Overview','◈'],['projects','Project commons','▣'],['foundry','Generative foundry','✧'],['ecosystem','Module ecosystem','⬡'],['innovation','Innovation genomes','🧬'],['prompt-lab','Prompt chain studio','⛓'],['methods','Method library','☷'],['capability','Capability lab','⇄'],['evidence','Evidence ledger','◉'],['safeguards','Safeguards','⛨'],['impact','Measurement lab','▤'],['exchange','Knowledge exchange','⬡'],['technology','Technology atlas','⌘'],['integrity','Integrity & QA','♧'],['manual','Research guides','☰'],['protocol-engines','Ten research engines','🔬'],['protocol-research','Research studio','⌁'],['protocol-models','Four scenario models','▥'],['fieldwork','Fieldwork & tasks','✓'],['migration','Legacy import & checks','⇪']];
const GATES=[['need','Need & rights-holders','Define the actual need, who identified it and whose rights are affected.'],['authority','Authority and consent','Verify owner, regulator, community and applicable Indigenous authority; document consent.'],['safety','Physical and domain safety','Use qualified reviewers; do not substitute software for food, health, engineering or legal approval.'],['privacy','Data minimization and privacy','Classify all information, avoid unnecessary identifiers, review share candidates and secure data appropriately.'],['equity','Accessibility and exclusion','Test keyboard/assistive access and identify groups bearing burdens or excluded from benefits.'],['evidence','Evidence and alternative','Define baseline, population, comparator, source quality, falsifier and negative-result reporting.'],['economics','Resources and continuity','Validate full lifecycle costs, paid work, maintenance, independent fallback and practical ownership.'],['reversibility','Adversarial review and exit','Identify misuse, conflicts, rollback, independent complaints and the right to decline or leave.']];
