const MUTATIONS={none:'No change: preserve selected methods and document alternatives.',offline:'Design for low bandwidth; embed core reference text and use honest local-only operation without fake live data.',youth:'Use age-appropriate language, adult-supported safety, privacy minimization and accessible controls without gating access.',evidence:'Pre-register measurable outcomes, comparator, uncertainty, falsifiers and null/negative-result reporting.',coop:'Specify governance, paid contributions, independent ownership, rights-holder consent, appeals and cost-free exit.',skills:'Translate capabilities and rewards into a supervised and credential-checked bridge without employment promises.',safety:'Perform a misuse and abuse inversion assessment with rollback, minimal permissions and outside review.',cross:'Combine methods from independent domains, document dependencies and evaluate conflicts instead of assuming synergy.',handover:'Include maintainer instructions, data schema, licensing, operations, backup/restore and a steward exit plan.'};
const $=id=>document.getElementById(id);
