const DEFAULT=()=>({format:'empowerment_foundry/2',schema:2,created:stamp(),projects:[],evidence:[],pathways:[],scenarios:[],fieldwork:[],gates:{},events:[],qa:{},customMethods:[],settings:{theme:'dark',motion:false,font:1},ecosystem:{customModules:[],projectModules:{}},innovation:{genomes:[],experiments:[]}});
let S=DEFAULT(),storageMode='memory',db=null,mem=null,writeQueue=Promise.resolve(),selectedProject='',currentRoute='home',generated='',generatedType='',childHtml='',childURL='',previewImport=null,publicPayload='',latestDigest='',lastDrawerFocus=null,toastTimer=null;
