function toast(message,bad=false){const t=$('toast');t.textContent=String(message);t.style.background=bad?'var(--red)':'var(--mint)';t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4100)}
function say(id,message){const node=$(id);if(node)node.textContent=message}
function down(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)}
async function copyText(t){if(!t){toast('Nothing to copy yet.',true);return}try{await navigator.clipboard.writeText(t);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable; select and copy the editable text instead.',true)}}
function log(action,details=''){S.events.push({id:uid(),date:stamp(),action,details:String(details).slice(0,350)});if(S.events.length>250)S.events=S.events.slice(-250)}
function savedStatus(){say('storage-status',storageMode==='indexeddb'?'Storage: IndexedDB':storageMode==='localstorage'?'Storage: localStorage':'Storage: memory only');say('footer-meta',`Storage: ${storageMode}; backup required for portability.`)}
async function initStorage(){if('indexedDB' in window){try{db=await new Promise((resolve,reject)=>{let request=indexedDB.open('foster_navi_empowerment_foundry',1);request.onupgradeneeded=()=>{let d=request.result;if(!d.objectStoreNames.contains('records'))d.createObjectStore('records')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('Database upgrade blocked'))});storageMode='indexeddb';return}catch(e){console.warn('IndexedDB unavailable',e)}}try{localStorage.setItem('__ef_test','1');localStorage.removeItem('__ef_test');storageMode='localstorage';return}catch(e){console.warn('localStorage unavailable',e)}storageMode='memory'}
function storeGet(){if(storageMode==='indexeddb')return new Promise((resolve,reject)=>{let r=db.transaction('records','readonly').objectStore('records').get('main');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)});if(storageMode==='localstorage')return Promise.resolve(JSON.parse(localStorage.getItem('empowerment_foundry_state_v1')||'null'));return Promise.resolve(mem)}
function storePut(snapshot){if(storageMode==='indexeddb')return new Promise((resolve,reject)=>{let t=db.transaction('records','readwrite');t.objectStore('records').put(snapshot,'main');t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)});if(storageMode==='localstorage'){localStorage.setItem('empowerment_foundry_state_v1',JSON.stringify(snapshot));return Promise.resolve()}mem=clone(snapshot);return Promise.resolve()}
async function recoverSave(snapshot){try{await storePut(snapshot)}catch(e){console.warn('Primary save failed',e);if(storageMode==='indexeddb'){try{localStorage.setItem('empowerment_foundry_state_v1',JSON.stringify(snapshot));storageMode='localstorage';toast('IndexedDB failed; switched to localStorage. Export a backup.',true);savedStatus();return}catch{}}storageMode='memory';mem=clone(snapshot);savedStatus();toast('Persistent storage failed. Export a backup now: data may vanish on reload.',true)}}
function persist(){const snapshot=clone(S);say('storage-status','Saving…');writeQueue=writeQueue.then(()=>recoverSave(snapshot)).then(()=>savedStatus());window.dispatchEvent(new CustomEvent('foundry:state'));return writeQueue}
function refresh(){renderStats();renderProjects();renderProjectSelects();refreshProtocolUI();renderFoundryMethods();renderFoundryTech();renderMethods();renderEvidence();renderGates();renderPathways();renderScenarios();renderQA();renderTechnology();drawGraph()}
function updateConnectivity(){const online=navigator.onLine;say('connectivity',online?'Network reported online · app local':'Network reported offline · app local')}
function applyPrefs(){document.documentElement.dataset.motion=S.settings.motion?'on':'off';document.documentElement.dataset.theme=S.settings.theme==='light'?'light':'dark';document.documentElement.style.setProperty('--font',Math.min(1.3,Math.max(.8,Number(S.settings.font)||1)));document.documentElement.style.scrollBehavior=S.settings.motion?'smooth':'auto';say('motion-btn','Motion: '+(S.settings.motion?'on':'off'));$('motion-btn').setAttribute('aria-pressed',String(!!S.settings.motion))}
function route(id,fromHash=false){if(!ROUTES.some(r=>r[0]===id)){id='home';toast('Unknown route; showing overview.',true)}currentRoute=id;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('#side-nav [data-route]').forEach(el=>{if(el.dataset.route===id)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});say('breadcrumb','Foundry / '+ROUTES.find(r=>r[0]===id)?.[1]);if(!fromHash&&location.hash!=='#'+id)location.hash=id;if(!fromHash)$('main').focus({preventScroll:true});closeDrawer();window.scrollTo({top:0,behavior:'instant'});if(id==='foundry')drawGraph()}
function showDrawer(){lastDrawerFocus=document.activeElement;$('sidebar').classList.add('open');$('mobile-cover').classList.add('open');$('mobile-open').setAttribute('aria-expanded','true');$('mobile-close').focus()}
function closeDrawer(){const open=$('sidebar').classList.contains('open');$('sidebar').classList.remove('open');$('mobile-cover').classList.remove('open');$('mobile-open').setAttribute('aria-expanded','false');if(open&&(lastDrawerFocus?.isConnected))lastDrawerFocus.focus()}
function renderNav(){const nav=$('side-nav');nav.replaceChildren();for(const [id,title,ico] of ROUTES){const b=document.createElement('button');b.type='button';b.className='navbtn';b.dataset.route=id;b.textContent=ico+'  '+title;nav.append(b)}}
function renderStats(){say('m-projects',S.projects.length);say('m-evidence',S.evidence.length);say('m-pathways',S.pathways.length);let all=Object.values(S.gates).flatMap(Object.values),done=all.filter(x=>x.status==='documented').length;say('m-gates',done+'/'+all.length);$('recent-projects').innerHTML='<h3>Local drafts</h3>'+(S.projects.slice(-3).reverse().map(p=>`<div class="listcard"><strong>${esc(p.title)}</strong><p>${esc(domain(p.domain).title)} · ${esc(p.stage)}</p><button class="btn tiny" type="button" data-edit-project="${esc(p.id)}">Open record</button></div>`).join('')||'<p class="small">No local projects yet.</p>')}
function projectFormClear(){say('project-form-title','Create a project');$('project-form').reset();$('project-id').value=''}
function projectFromForm(){return{id:$('project-id').value||uid(),title:txt($('project-title').value),domain:$('project-domain').value,scale:$('project-scale').value,place:txt($('project-place').value),audience:txt($('project-audience').value),need:txt($('project-need').value),goal:txt($('project-goal').value),constraints:txt($('project-constraints').value),owner:txt($('project-owner').value),stage:$('project-stage').value,methods:[],technologies:[],created:stamp(),updated:stamp()}}
function editProject(id){let p=P(id);if(!p)return;route('projects');for(const [field,key] of [['id','id'],['title','title'],['domain','domain'],['scale','scale'],['place','place'],['audience','audience'],['need','need'],['goal','goal'],['constraints','constraints'],['owner','owner'],['stage','stage']])$('project-'+field).value=p[key]||'';say('project-form-title','Edit project · '+p.title);$('project-title').focus()}
function saveProject(ev){ev.preventDefault();if(!$('project-form').reportValidity())return;const x=projectFromForm();if(!x.title||!x.place||!x.need||!x.goal){toast('Title, location, problem and outcome are required.',true);return}const at=S.projects.findIndex(p=>p.id===x.id);if(at>=0){x.methods=S.projects[at].methods||[];x.technologies=S.projects[at].technologies||[];x.created=S.projects[at].created;S.projects[at]=x;log('project_updated',x.id)}else{if(S.projects.length>=300){toast('300-project limit; export your archive first.',true);return}S.projects.push(x);log('project_created',x.id)}selectedProject=x.id;invalidateOutput();persist();projectFormClear();refresh();toast('Project saved locally. This is a self-reported record.')}
function renderProjects(){const q=cap($('projects-search').value);let rows=S.projects.filter(p=>!q||JSON.stringify(p).toLocaleLowerCase().includes(q));$('project-list').innerHTML=rows.map(p=>`<article class="listcard"><div class="row"><span class="badge">${esc(domain(p.domain).title)}</span><span class="badge">${esc(p.stage)}</span></div><h3>${esc(p.title)}</h3><p><strong>Context:</strong> ${esc(p.place)} · ${esc(p.scale)}</p><p><strong>Problem:</strong> ${esc(p.need)}</p><p><strong>Outcome:</strong> ${esc(p.goal)}</p><p class="small">${(p.methods||[]).length} methods · ${esc(p.updated?.slice(0,10)||'No time')}</p><div class="row"><button class="btn tiny" type="button" data-edit-project="${esc(p.id)}">Edit</button><button class="btn tiny" type="button" data-use-project="${esc(p.id)}">Open foundry</button><button class="btn tiny" type="button" data-copy-project="${esc(p.id)}">Fork</button><button class="btn tiny critical" type="button" data-delete-project="${esc(p.id)}">Delete</button></div></article>`).join('')||'<p class="small">No matching projects. Records created here are local until deliberately exported.</p>'}
function selected(){return P($('foundry-project').value||selectedProject)}
function fillSelect(id,includeBlank=false){const el=$(id),prior=el.value;el.replaceChildren();if(includeBlank){const o=new Option('Unassigned','');el.add(o)}for(let p of S.projects)el.add(new Option(p.title+' · '+p.place,p.id));el.value=(id==='foundry-project'&&S.projects.some(p=>p.id===selectedProject))?selectedProject:S.projects.some(p=>p.id===prior)?prior:S.projects.some(p=>p.id===selectedProject)?selectedProject:(includeBlank?'':S.projects[0]?.id||'')}
function renderProjectSelects(){for(const id of ['foundry-project','cap-project','ev-project','gate-project','sc-project'])fillSelect(id,id==='ev-project'||id==='cap-project'||id==='sc-project');if(!selectedProject&&S.projects[0])selectedProject=S.projects[0].id}
function renderFoundryMethods(){const p=selected(),q=cap($('foundry-filter').value);const rows=methods().filter(m=>!q||[m.title,m.overview,m.action,m.metric,m.risk,domain(m.domain).title].join(' ').toLowerCase().includes(q));$('foundry-methods').innerHTML=rows.map(m=>`<label class="checkrow listcard"><input type="checkbox" data-pick-method="${esc(m.id)}" ${p?.methods?.includes(m.id)?'checked':''} ${p?'':'disabled'}><span><strong>${esc(m.title)}</strong><br><small>${esc(domain(m.domain).title)} · ${esc(m.action)}</small></span></label>`).join('')||'<p class="small">No methods match this filter.</p>';say('foundry-summary',p?`${p.title}: ${(p.methods||[]).length} selected methods; ${(p.technologies||[]).length} technology references.`:'Create a project in Project commons to activate generation.')}
function renderFoundryTech(){const p=selected(),q=cap($('tech-select-filter').value);const rows=EMBED.technology.filter(t=>!q||JSON.stringify(t).toLowerCase().includes(q)).slice(0,63);$('foundry-tech').innerHTML=rows.map(t=>`<label class="checkrow"><input type="checkbox" data-pick-tech="${esc(t.id)}" ${p?.technologies?.includes(t.id)?'checked':''} ${p?'':'disabled'}><span><strong>${esc(t.title)}</strong><br><small>${esc(t.summary)}</small></span></label>`).join('')||'<p class="small">No technology references found.</p>'}
function renderMethods(){const q=cap($('method-search').value),group=$('method-domain').value;let rows=methods().filter(m=>(group==='all'||m.domain===group)&&(!q||JSON.stringify(m).toLocaleLowerCase().includes(q)));say('method-count',`${rows.length} of ${methods().length} method definitions visible; ${S.customMethods.length} imported definitions.`);$('method-list').innerHTML=rows.map(m=>`<article class="listcard"><span class="topic-tag">${esc(domain(m.domain).title)} · ${esc(m.id)}</span><h3>${esc(m.title)}</h3><p>${esc(m.overview)}</p><details><summary>Method, measurement, constraints and acceptance</summary><div class="detail"><p><strong>Practical output:</strong> ${esc(m.action)}</p><p><strong>Evidence target:</strong> ${esc(m.metric)}</p><p><strong>Stop/failure condition:</strong> ${esc(m.risk)}</p><h4>Implementation checks</h4><ol>${(m.readiness||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></details><button type="button" class="btn tiny" data-attach-method="${esc(m.id)}">Attach to active project</button></article>`).join('')||'<p>No methods match. Clear filters.</p>'}
function renderTechnology(){const q=cap($('technology-search').value),type=$('technology-group').value;const rows=EMBED.technology.filter(t=>(type==='all'||t.category===type)&&(!q||JSON.stringify(t).toLowerCase().includes(q)));say('technology-count',`${rows.length} of ${EMBED.technology.length} descriptions visible.`);$('technology-list').innerHTML=rows.map(t=>`<article class="listcard"><span class="badge">${esc(t.category)}</span><h3>${esc(t.title)}</h3><p>${esc(t.summary)}</p><p class="small">Source path in supplied ZIP: <code>${esc(t.id)}</code></p><p class="small">Topics: ${esc(t.tags)}</p><button type="button" class="btn tiny" data-attach-tech="${esc(t.id)}">Use as foundry reference</button></article>`).join('')}
function describeProject(p){return {id:p.id,title:p.title,domain:p.domain,scale:p.scale,place:p.place,audience:p.audience,need:p.need,goal:p.goal,constraints:p.constraints,owner:p.owner,stage:p.stage,created:p.created,updated:p.updated}}
function blueprint(p){const mids=(p.methods||[]).map(M).filter(Boolean);const tech=(p.technologies||[]).map(id=>EMBED.technology.find(x=>x.id===id)).filter(Boolean);return {format:'empowerment_blueprint/1',created_local:stamp(),project:describeProject(p),methods:mids.map(m=>({id:m.id,domain:m.domain,title:m.title,mechanism:m.overview,procedure:m.action,indicator:m.metric,risk:m.risk,checks:m.readiness||[]})),technology:tech.map(t=>({id:t.id,title:t.title,summary:t.summary,implementation_included:false})),configuration:{users:txt($('foundry-audience').value)||p.audience||'Affected rights-holders and intended users',deployment:$('foundry-device').value,extra_constraints:txt($('foundry-constraint').value),mutation:$('foundry-mutation').value,variation_rule:MUTATIONS[$('foundry-mutation').value]},evidence_refs:S.evidence.filter(e=>e.projectId===p.id).map(e=>({id:e.id,type:e.type,status:e.status,source:e.source,limitations:e.limit})),safeguards:GATES.map(([id,title,description])=>({id,title,description,record:S.gates[p.id]?.[id]||{status:'not_assessed'}})),acceptance:['Every displayed UI action has a real, tested consequence or is omitted.','Imported data is size-bounded, schema validated and safely rendered.','Offline claims match tested conditions; live features have explicit failure paths.','Permissions, authority, safety, evidence and human review are independently established.','Demonstrate export/import round-trip, keyboard navigation and error recovery.'],limitations:['This JSON is a specification, not proof of implementation.','No third-party authority, source truth or deployment is verified by this application.']}}
function makePrompt(b){let x=[`FOSTER + NAVI · GENERATIVE IMPLEMENTATION CONTRACT · ${b.project.title}`,`Created using local clock: ${b.created_local}. This timestamp is NOT independent proof of precedence.`,`\nCONTEXT\nProject: ${b.project.title}\nLocation: ${b.project.place}\nScale: ${b.project.scale}\nAffected people: ${b.configuration.users}\nObserved problem: ${b.project.need}\nIntended measurable outcome: ${b.project.goal}\nKnown constraints: ${b.project.constraints}\nDeployment preference: ${b.configuration.deployment}\nAdditional requirements: ${b.configuration.extra_constraints||'None supplied'}`,`\nCHOSEN EMPOWERMENT METHODS (${b.methods.length})`];b.methods.forEach((m,i)=>x.push(`${i+1}. ${m.title} [${m.id}]\n   Mechanism: ${m.mechanism}\n   Implementation: ${m.procedure}\n   Evidence: ${m.indicator}\n   Failure/stop: ${m.risk}\n   Prerequisites: ${(m.checks||[]).join('; ')}`));x.push(`\nTECHNOLOGIES TO EVALUATE (${b.technology.length}; references, not preinstalled implementation)`);b.technology.forEach(t=>x.push(`- ${t.title} [${t.id}]: ${t.summary}. Do not invent API coverage; check availability, licensing, permission, accessibility and offline fallback.`));x.push(`\nREQUIRED DESIGN VARIATION\n${b.configuration.variation_rule}`,`\nSYSTEM-LEVEL MANDATORY REQUIREMENTS\n1. Clarify user agency, lawful context, consent and scope before coding; do not infer any political preference or steer electoral choices.\n2. Deliver a genuinely working artifact. Prefer complete standalone semantic HTML5 with embedded CSS and vanilla JS when small; use a versioned hosted PWA only when separate files and real service-worker hosting are supplied.\n3. ONE route registry drives top/side navigation, breadcrumbs, mobile drawer, unknown-route recovery, keyboard Escape and focus management. Every button must work.\n4. Core reading and recorded work should function offline if saved. Show precise network, storage, freshness, pending-action and unavailable-feature states. File:// pages cannot use standard service workers.\n5. IndexedDB first if appropriate with tested fallback, schema versioning/migrations, meaningful quota handling and explicitly reviewed import/merge/replace; reversible destructive actions and local JSON backups.\n6. Human-safe interfaces: semantic labels, accessible focus, contrast, mobile/zoom, reduced motion, printed output and honest no-JS reading where feasible. Never make gamification gate essentials.\n7. Use no hidden analytics, automatic emails, secret transfers, forged citations, invented endpoints or hardcoded credentials. Do not execute imported code or render untrusted HTML.\n8. Maintain observations, inferences, hypotheses, simulation and metaphor as separate data types. Cite source dates and claims; expose contrary evidence and explicit falsifiers.\n9. For human/economic/ecological outcomes define baselines, population, units, denominator, data collection, suitable comparator, confounders, adverse results and stop conditions.\n10. Include a qualified-review and zero-harm/anti-inversion gate; retain consent, accessibility, exit, independent audit and lawful authority.\n11. For any optional real service, document permission, network requirements, secure origin, failure and consent-based fallback; do not pretend a mock integration is connected.\n12. Make project metadata, source licensing, SHA-256 integrity limitations, attributions and a concise deployment guide explicit. A hash is not a timestamp or signature.\n13. Provide tests for each advertised interaction and report which tests actually ran vs remain manual. Do not claim real-world impact without measurements.\n14. At the end, identify unresolved risks and formulate at least three additional user-empowering design questions, answer them provisionally, and label hypotheses.\n\n8 RIGHTS/SAFETY GATES (self-reported status in source blueprint; not legal approval):`);b.safeguards.forEach(g=>x.push(`- ${g.title}: ${g.description} Status=${g.record.status}; Notes=${g.record.note||'unprovided'}; reference=${g.record.reference||'unprovided'}`));x.push(`\nEVIDENCE POINTERS (${b.evidence_refs.length}): ${b.evidence_refs.length?JSON.stringify(b.evidence_refs):'No evidence supplied; seek independent verification.'}`,`\nDELIVERABLES\nA. Architecture and user journeys with full working controls.\nB. Complete source and explicit integration boundaries.\nC. Domain-specific research table: claim, source, date, uncertainty, conflicting evidence.\nD. Data schema with export/import examples and migration/backup test.\nE. Threat model, accessibility checklist, unit tests, manual browser tests, and actual test results.\nF. Reversible 30/60/90-day field plan plus longer real-world lead-time warnings.\nG. A standalone method/knowledge pack that others can adapt without an account.\n\nRULE: do not fabricate current law, partners, deployment, certifications, data, live APIs or outcomes. Ask for missing facts only when truly blocking; otherwise label assumptions and provide a bounded safe draft.`);return x.join('\n')}
function makeGuide(b){const p=b.project;return `FIELD GUIDE · ${p.title}\n==============================\nContext: ${p.place}; scale: ${p.scale}; audience: ${b.configuration.users}.\nProblem: ${p.need}\nGoal: ${p.goal}\n\nSTEP 1 · EVIDENCE: Document baseline, population, units, method and at least one credible alternative.\nSTEP 2 · GOVERNANCE: Identify actual authority, rights-holder consent, professional safety gates and lawful participation.\nSTEP 3 · DESIGN: ${b.methods.length?b.methods.map((m,i)=>`\n  ${i+1}. ${m.title}: ${m.procedure}\n     Measure: ${m.indicator}\n     Avoid: ${m.risk}`).join(''):'No methods chosen: return to the library and select at least one method.'}\nSTEP 4 · FIELD TEST: Pilot reversibly with an owner, budget, comparison, independent evaluation and stop condition.\nSTEP 5 · HANDOVER: Verify results, record failures, review privacy, provide a portable backup and document an exit process.\n\nDESIGN MUTATION: ${b.configuration.variation_rule}\nTECHNOLOGY REFERENCES: ${b.technology.map(t=>t.title).join('; ')||'None selected'}\n\nLIMITATIONS: This guide is generated from self-entered local text and built-in planning descriptions. It is not site-specific engineering, clinical/legal advice, approval or validated impact evidence.`}
function invalidateOutput(){childHtml='';generated='';say('child-status','Inputs changed. Regenerate the child before previewing or downloading.')}
function doGenerate(){const p=selected();if(!p){toast('Create a project first.',true);return}const b=blueprint(p);generatedType=$('foundry-output-kind').value;generated=generatedType==='blueprint'?JSON.stringify(b,null,2):generatedType==='guide'?makeGuide(b):makePrompt(b);$('output-text').value=generated;say('foundry-summary',`${p.title} · ${b.methods.length} methods · ${b.technology.length} tech references · ${generatedType} · ${new TextEncoder().encode(generated).byteLength} bytes.`);toast('Generated artifact is editable. Verify sources and assumptions.')}
function outputDownload(){const body=$('output-text').value;if(!body)return toast('Generate a result first.',true);down(generatedType==='blueprint'?'empowerment_blueprint.json':generatedType==='guide'?'empowerment_field_guide.txt':'empowerment_implementation_prompt.txt',body,generatedType==='blueprint'?'application/json':'text/plain')}
function drawGraph(){const g=$('method-graph'),p=selected();g.replaceChildren();const items=p?.methods?.map(M).filter(Boolean)||[];if(!items.length){g.textContent='Select a project and its methods to display their conceptual connections.';say('graph-text','No selected methods.');return}const NS='http://www.w3.org/2000/svg',height=Math.max(185,items.length*62+28),svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox',`0 0 840 ${height}`);svg.setAttribute('role','img');svg.setAttribute('aria-label','Project connected to '+items.map(x=>x.title).join(', '));function element(t,a,content){let n=document.createElementNS(NS,t);for(let [k,v] of Object.entries(a))n.setAttribute(k,String(v));if(content!==undefined)n.textContent=content;svg.append(n);return n}const cy=height/2;element('rect',{x:12,y:cy-23,width:232,height:46,rx:9,fill:'#175842',stroke:'#87ebbd'});element('text',{x:24,y:cy+5,fill:'#ffffff','font-size':13},p.title.slice(0,31));items.forEach((m,i)=>{let y=35+i*62;element('line',{x1:244,y1:cy,x2:310,y2:y,stroke:'#82bcc0','stroke-width':1.5});element('rect',{x:310,y:y-22,width:508,height:44,rx:8,fill:'#233d4b',stroke:'#82bcc0'});element('text',{x:322,y:y+4,fill:'#f4ffff','font-size':12},m.title.slice(0,62))});g.append(svg);say('graph-text',`${p.title} conceptually combines: `+items.map(m=>m.title).join('; ')+'. Connections do not prove causation or compatibility.')}
/* Bounded child compiler. Its generated JS never interpolates untrusted text into executable syntax;
   project data is a JSON-only script with '<' escaped. Child record text is inserted via textContent. */
function childSource(p){const b=blueprint(p),tasks=[{id:uid(),name:'Verify actual baseline and affected rights-holders',done:false,note:''},{id:uid(),name:'Confirm consent, legal authority and safety boundaries',done:false,note:''},...b.methods.map(m=>({id:uid(),name:m.title+' · '+m.procedure,done:false,note:''})),{id:uid(),name:'Document comparable results, adverse findings and handover',done:false,note:''}];const seed={format:'empowerment_child/1',id:p.id,title:p.title,goal:p.goal,place:p.place,methods:b.methods.map(m=>({id:m.id,title:m.title,metric:m.indicator,risk:m.risk})),tasks,notes:'',version:1};const safeJSON=JSON.stringify(seed).replace(/</g,'\\u003c');const childLicense='MIT License · Copyright (c) 2026 Foster + Navi. Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the Software), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to inclusion of this copyright and permission notice. THE SOFTWARE IS PROVIDED AS IS, WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY.';const childJS=String.raw`
'use strict';(()=>{const seed=JSON.parse(document.getElementById('seed').textContent),$=id=>document.getElementById(id);let state=seed,storeOK=false;const key='empowerment_child_'+seed.id;function say(x){$('status').textContent=x}function save(){try{localStorage.setItem(key,JSON.stringify(state));storeOK=true;say('Saved to browser localStorage. Export JSON for durability.')}catch{storeOK=false;say('Memory only: persistent storage unavailable. Export JSON now.')}}try{const raw=localStorage.getItem(key);if(raw){const s=JSON.parse(raw);if(s.format===seed.format&&s.id===seed.id&&Array.isArray(s.tasks))state=s}}catch{}function download(n,t){let u=URL.createObjectURL(new Blob([t],{type:'application/json'})),a=document.createElement('a');a.download=n;a.href=u;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000)}function render(){const dest=$('items');dest.replaceChildren();state.tasks.forEach(t=>{let section=document.createElement('article');section.className='task';let label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=!!t.done;check.onchange=()=>{t.done=check.checked;save();render()};let name=document.createElement('span');name.textContent=t.name;label.append(check,name);let input=document.createElement('textarea');input.value=t.note||'';input.placeholder='Evidence, next action or limitation (stored only on this device)';input.maxLength=1000;input.onchange=()=>{t.note=input.value;save()};let del=document.createElement('button');del.type='button';del.textContent='Delete task';del.onclick=()=>{if(!confirm('Delete this task?'))return;state.tasks=state.tasks.filter(v=>v.id!==t.id);save();render()};section.append(label,input,del);dest.append(section)});$('count').textContent=state.tasks.filter(t=>t.done).length+' / '+state.tasks.length+' self-reported tasks complete (not real-world verification)';$('notes').value=state.notes||''}$('new-form').onsubmit=e=>{e.preventDefault();let v=$('new-task').value.trim();if(!v)return;state.tasks.push({id:'task_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2),name:v.slice(0,240),done:false,note:''});$('new-task').value='';save();render()};$('notes').onchange=()=>{state.notes=$('notes').value;save()};$('export').onclick=()=>download('independent_project_backup.json',JSON.stringify(state,null,2));$('import').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>1000000)throw Error('File over 1 MB');let x=JSON.parse(await f.text());if(x.format!==seed.format||x.id!==seed.id||!Array.isArray(x.tasks)||x.tasks.length>200||x.tasks.some(t=>!t||typeof t.name!=='string'||typeof t.id!=='string'||typeof t.done!=='boolean'||t.name.length>240))throw Error('Incompatible or invalid backup');if(!confirm('Replace local child data with validated backup?'))return;state={...seed,tasks:x.tasks.map(t=>({id:t.id.slice(0,120),name:t.name,done:t.done,note:String(t.note||'').slice(0,1000)})),notes:String(x.notes||'').slice(0,6000)};save();render();say('Child backup imported.')}catch(err){say('Import rejected: '+err.message)}e.target.value=''};$('reset').onclick=()=>{if(!confirm('Reset this child project to its initial tasks? Export a backup first.'))return;state=JSON.parse(JSON.stringify(seed));save();render()};$('remix').onclick=()=>{const p='Create an accessible, independent project implementation for '+state.title+' in '+state.place+'. Intended outcome: '+state.goal+'. Keep local JSON portability, consent, safety, evidence, editable task tracking and truthful offline limitations. Methods: '+state.methods.map(m=>m.title+' — '+m.metric+'; avoid '+m.risk).join(' | ')+'. Produce verified tests and label assumptions. Do not invent outcomes.';$('remix-text').value=p};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('remix-text').value);say('Remix prompt copied.')}catch{say('Clipboard unavailable; select the text manually.')}};render();say(storeOK?'Stored locally; export regular backups.':'Browser storage may be unavailable; export for durability.');})();`;
return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"><title>${esc(p.title)} · Independent empowerment module</title><style>:root{color-scheme:dark light;font:16px/1.55 system-ui}body{max-width:1000px;margin:0 auto;padding:20px;background:#0b1a25;color:#f0fbf9}a{color:#a6d7ff}button,input,textarea{font:inherit}button{cursor:pointer;background:#163b3c;color:#f6fff8;border:1px solid #7aab9b;border-radius:8px;padding:9px;margin:4px}input,textarea{background:#102d37;color:#fff;border:1px solid #8baca9;padding:10px;border-radius:7px;max-width:100%}input[type=text],textarea{width:100%}textarea{min-height:65px}label{display:flex;gap:12px;align-items:start}label span{flex:1}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #f9d886}main,header,footer{display:block}section,.task{border:1px solid #426769;border-radius:12px;padding:15px;margin:12px 0;background:#112735}.task button{display:block}.muted{color:#b2cccc}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media print{button,input[type=file],form{display:none}body{background:white;color:black}.task,section{background:white;color:black;border:1px solid #666}}</style></head><body><a href="#main">Skip to main</a><header><p class="muted">Foster + Navi · locally generated independent tool · no accounts or telemetry</p><h1>${esc(p.title)}</h1><p>${esc(p.goal)}</p><p class="muted">${esc(p.place)} · draft only; no approvals or outcomes are verified.</p></header><main id="main"><section><h2>Project work</h2><p id="count"></p><p id="status" role="status">Local storage status pending.</p><div id="items"></div><form id="new-form"><label for="new-task">Add your own task</label><input id="new-task" type="text" required maxlength="240"><button type="submit">Add task</button></form></section><section><h2>Working notes</h2><label for="notes">Notes are stored locally, without encryption</label><textarea id="notes" maxlength="6000"></textarea></section><section><h2>Portable project data</h2><button type="button" id="export">Download private JSON</button><label for="import">Import matching child JSON</label><input id="import" type="file" accept="application/json,.json"><button type="button" id="reset">Reset child (confirm)</button><p class="muted">Saving to a browser is not permanent; export backups. No network services are included.</p></section><section><h2>Pass the method forward</h2><button id="remix" type="button">Generate remix prompt</button><button id="copy" type="button">Copy prompt</button><label for="remix-text">Editable prompt for a separate AI or developer</label><textarea id="remix-text" style="min-height:180px"></textarea></section><footer>MIT · Foster + Navi · derived from a locally configured foundry blueprint. This app cannot independently verify permissions, sources, skills or impact.<details><summary>License and permissions</summary><p>${esc(childLicense)}</p></details></footer></main><script type="application/json" id="seed">${safeJSON}</scr`+`ipt><scr`+`ipt>${childJS}</scr`+`ipt></body></html>`}
function generateChild(){const p=selected();if(!p)return toast('Create or select a project first.',true);childHtml=childSource(p);say('child-status',`Standalone HTML generated for ${p.title} · ${new TextEncoder().encode(childHtml).byteLength} bytes. Preview/download to validate.`);toast('Child application compiled in memory; download to retain it.')}
function previewChild(){if(!childHtml)generateChild();if(!childHtml)return;if(childURL)URL.revokeObjectURL(childURL);childURL=URL.createObjectURL(new Blob([childHtml],{type:'text/html'}));$('child-frame').src=childURL;toast('Sandbox preview loaded. Browser storage can be restricted in this preview.')}
function downloadChild(){if(!childHtml)generateChild();if(childHtml)down('index.html',childHtml,'text/html')}
function renderPathways(){const dest=$('pathway-list');dest.innerHTML=S.pathways.slice().reverse().map(x=>`<article class="listcard"><h3>${esc(x.source)} → ${esc(x.target)}</h3><p class="small">${esc(x.date.slice(0,10))} · ${x.shared.length} exact shared · ${x.bridges.length} target gaps</p><p>Shared: ${esc(x.shared.join('; ')||'None detected')}</p><p>Bridge: ${esc(x.bridges.join('; ')||'None detected')}</p><p class="small">No hiring or qualification claim is made.</p><button class="btn tiny critical" data-del-path="${esc(x.id)}" type="button">Delete</button></article>`).join('')||'<p class="small">No saved pathways.</p>'}
function pathwaySave(ev){ev.preventDefault();if(!$('pathway-form').reportValidity())return;let current=list($('cap-known').value),target=list($('cap-needed').value),shared=current.filter(x=>target.includes(x)),bridges=target.filter(x=>!current.includes(x)),extra=current.filter(x=>!target.includes(x));let obj={id:uid(),projectId:$('cap-project').value,source:txt($('cap-source').value),target:txt($('cap-target').value),current,targetCaps:target,shared,bridges,extra,rewards:txt($('cap-rewards').value),risks:txt($('cap-risks').value),verification:txt($('cap-test').value),date:stamp()};S.pathways.push(obj);log('pathway_hypothesis_saved',obj.id);persist();$('cap-output').innerHTML=`<div class="listcard"><h3>Exact normalized overlap: ${shared.length} capabilities</h3><p>${esc(shared.join(' · ')||'No literal overlaps. Similar words and levels are not inferred.')}</p><h3>Target gaps: ${bridges.length}</h3><p>${esc(bridges.join(' · ')||'No literal gaps detected; qualifications still need verification.')}</p><h3>Other source capabilities</h3><p>${esc(extra.join(' · ')||'None entered.')}</p><p><strong>Rewards to preserve:</strong> ${esc(obj.rewards||'Not supplied')}</p><p><strong>Credential and safety checks:</strong> ${esc(obj.risks||'Not supplied')}</p><p><strong>External verification:</strong> ${esc(obj.verification||'Not supplied')}</p><div class="callout warn">Exact keyword overlap is not competence, salary, licensing, training eligibility or employment. This is a participant-controlled hypothesis.</div></div>`;renderPathways();renderStats();toast('Pathway hypothesis saved, not validated.')}
function renderEvidence(){const q=cap($('evidence-filter').value);let rows=S.evidence.filter(e=>!q||JSON.stringify(e).toLowerCase().includes(q));$('evidence-list').innerHTML=rows.slice().reverse().map(e=>`<article class="listcard"><div class="row"><span class="badge">${esc(e.type)}</span><span class="badge warn">${esc(e.status)}</span></div><h3>${esc(e.claim)}</h3><p class="small">Project: ${esc(P(e.projectId)?.title||'Unassigned')} · ${esc(e.date.slice(0,10))}</p><p><strong>Source / method:</strong> ${esc(e.source||'None supplied')}</p><p><strong>Uncertainty:</strong> ${esc(e.limit)}</p><details><summary>Falsifier and boundaries</summary><div class="detail">${esc(e.falsifier||'No falsifier supplied. The claim needs more scrutiny.')}</div></details><button type="button" class="btn tiny critical" data-del-evidence="${esc(e.id)}">Delete record</button></article>`).join('')||'<p class="small">No evidence records found.</p>'}
function evidenceSave(ev){ev.preventDefault();if(!$('evidence-form').reportValidity())return;const e={id:uid(),projectId:$('ev-project').value,claim:txt($('ev-claim').value),type:$('ev-type').value,status:$('ev-status').value,source:txt($('ev-source').value),limit:txt($('ev-limit').value),falsifier:txt($('ev-falsifier').value),date:stamp()};if(!e.claim||!e.limit)return toast('Claim and uncertainty are required.',true);S.evidence.push(e);log('evidence_record_added',e.id);persist();$('evidence-form').reset();renderProjectSelects();renderEvidence();renderStats();toast('Evidence stored. Selected review status is not independently authenticated.')}
function renderGates(){const id=$('gate-project').value,p=P(id);if(!p){say('gate-summary','Create a project before recording safeguards.');$('gate-list').replaceChildren();return}const o=S.gates[p.id]||{},documented=Object.values(o).filter(x=>x.status==='documented').length,blocked=Object.values(o).filter(x=>x.status==='blocked').length;say('gate-summary',`${p.title}: ${documented}/8 gates documented by the user, ${blocked} blocked. No status represents official approval.`);$('gate-list').innerHTML=GATES.map(([gid,title,description],i)=>{const x=o[gid]||{status:'not_assessed',note:'',reference:''};return `<article class="listcard" data-gate="${gid}"><h3>${i+1}. ${esc(title)}</h3><p>${esc(description)}</p><div class="formgrid"><div class="field"><label for="gate-status-${gid}">Self-reported gate status</label><select id="gate-status-${gid}"><option value="not_assessed" ${x.status==='not_assessed'?'selected':''}>Not assessed</option><option value="documented" ${x.status==='documented'?'selected':''}>Documented (self-reported)</option><option value="blocked" ${x.status==='blocked'?'selected':''}>Blocked</option></select></div><div class="field"><label for="gate-ref-${gid}">External evidence / reviewer reference</label><input id="gate-ref-${gid}" maxlength="500" value="${esc(x.reference||'')}" placeholder="Record title and responsible reviewer"></div><div class="field full"><label for="gate-note-${gid}">Notes and remaining limits</label><textarea id="gate-note-${gid}" maxlength="1200">${esc(x.note||'')}</textarea></div></div><button class="btn tiny" type="button" data-save-gate="${gid}">Save gate record</button></article>`}).join('')}
function saveGate(id){const p=P($('gate-project').value);if(!p)return;const status=$('gate-status-'+id).value,note=txt($('gate-note-'+id).value),reference=txt($('gate-ref-'+id).value);if(status==='documented'&&(!note||!reference)){toast('A self-reported documented gate requires notes and an external evidence reference.',true);return}if(!S.gates[p.id])S.gates[p.id]={};S.gates[p.id][id]={status,note,reference,updated:stamp()};log('gate_recorded',p.id+':'+id+':'+status);persist();renderGates();renderStats();toast('Gate recorded as self-report; not an external clearance.')}
function renderScenarios(){const body=$('scenario-table'),items=S.scenarios.slice().reverse();body.innerHTML=items.map(s=>`<tr><td>${esc(s.name)}<br><small>${esc(P(s.projectId)?.title||'Unassigned')} · ${esc(s.unit)}</small></td><td class="num">${fmt(s.before)}</td><td class="num">${fmt(s.after)}</td><td class="num">${fmt(s.delta)}</td><td>${esc(s.kind)}</td><td><button class="btn tiny critical" type="button" data-del-scenario="${esc(s.id)}">Delete</button></td></tr>`).join('')||'<tr><td colspan="6">No saved numbers. Add a transparent observation or hypothetical scenario.</td></tr>';const bars=$('impact-bars');bars.replaceChildren();const recent=items.slice(0,6),abs=Math.max(1,...recent.flatMap(s=>[Math.abs(s.before),Math.abs(s.after)]));for(const s of recent){let article=document.createElement('div');article.className='listcard';let title=document.createElement('strong');title.textContent=s.name+' ('+s.unit+')';article.append(title);for(const [name,value] of [['Baseline',s.before],['Follow-up',s.after]]){const line=document.createElement('div');line.className='small';line.textContent=name+': '+fmt(value);const track=document.createElement('div');track.className='bar';const fill=document.createElement('span');fill.style.width=(Math.abs(value)/abs*100)+'%';fill.title='Absolute magnitude only; negative sign retained in numeric label';track.append(fill);article.append(line,track)}bars.append(article)}say('impact-insight',`${S.scenarios.length} user-entered scenario/measurement records. Bars reflect absolute magnitudes; read signed numeric values in the table. No attribution or external validation is performed.`)}
function scenarioSave(ev){ev.preventDefault();if(!$('scenario-form').reportValidity())return;const before=num($('sc-before').value),after=num($('sc-after').value),cost=num($('sc-cost').value),people=num($('sc-people').value);if(!Number.isFinite(before)||!Number.isFinite(after)||Math.abs(before)>1e12||Math.abs(after)>1e12||($('sc-cost').value&&(!Number.isFinite(cost)||cost<0))||($('sc-people').value&&(!Number.isSafeInteger(people)||people<0))){toast('Enter finite quantities, nonnegative cost and a whole number of people.',true);return}let row={id:uid(),projectId:$('sc-project').value,name:txt($('sc-name').value),unit:txt($('sc-unit').value),kind:$('sc-kind').value,before,after,delta:after-before,cost:Number.isFinite(cost)?cost:null,people:Number.isFinite(people)?people:null,method:txt($('sc-method').value),date:stamp()};if(!row.method||!row.unit)return toast('Measurement method and unit are mandatory.',true);S.scenarios.push(row);log('scenario_entered',row.id);persist();$('scenario-form').reset();renderProjectSelects();renderScenarios();let note=`${row.name}: baseline ${fmt(before)} → follow-up ${fmt(after)} ${row.unit}; descriptive difference ${fmt(row.delta)}. No causal claim.`;if(row.cost!==null&&row.people>0)note+=` Recorded cost per person: ${fmt(row.cost/row.people)} currency units; only meaningful with a defined currency, timeframe and denominator.`;say('impact-insight',note);toast('Numeric record saved. No real-world impact certified.')}
function qaRenderLine(t,i){const x=S.qa[i]||{checked:false,note:''};return `<div class="listcard"><label class="checkrow" for="qa-check-${i}"><input type="checkbox" id="qa-check-${i}" data-qa-check="${i}" ${x.checked?'checked':''}><span>${esc(t)}</span></label><label for="qa-note-${i}">Test evidence / limitations</label><input type="text" id="qa-note-${i}" data-qa-note="${i}" maxlength="360" value="${esc(x.note||'')}" placeholder="Browser, test steps, failures…"></div>`}
function renderQA(){say('qa-summary',`${Object.values(S.qa).filter(x=>x.checked).length} / ${QA.length} self-reported review items. This file does not automatically validate browser accessibility, security or domain correctness.`);$('qa-list').innerHTML=QA.map(qaRenderLine).join('')}
function renderEnvironment(){const checks=[['Protocol',location.protocol],['Secure context',String(isSecureContext)],['Network report',navigator.onLine?'online':'offline'],['IndexedDB',String('indexedDB'in window)],['Crypto.subtle',String(!!crypto?.subtle)],['BroadcastChannel',String('BroadcastChannel'in window)],['Service worker',location.protocol==='file:'?'Unavailable on file:// (standalone still works)':document.querySelector('link[rel=manifest]')?'PWA companion provided (check registration below)':'Not bundled with standalone HTML'],['Persistence mode',storageMode]];$('environment').innerHTML=checks.map(([a,b])=>`<div class="info-pair"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}
function searchGlobal(){const q=cap($('global-search').value),dest=$('search-results');if(q.length<2){dest.hidden=true;return}let results=[];for(const e of PROTOCOL_ENGINES)if(JSON.stringify(e).toLowerCase().includes(q))results.push({t:'engine',name:e.name,sub:'Detailed Protocol engine',id:e.id});for(const m of methods())if(JSON.stringify(m).toLowerCase().includes(q))results.push({t:'method',name:m.title,sub:domain(m.domain).title,id:m.id});for(const t of EMBED.technology)if(JSON.stringify(t).toLowerCase().includes(q))results.push({t:'tech',name:t.title,sub:t.category,id:t.id});for(const p of S.projects)if(JSON.stringify(p).toLowerCase().includes(q))results.push({t:'project',name:p.title,sub:p.place,id:p.id});for(const r of ROUTES)if(r[1].toLowerCase().includes(q))results.push({t:'route',name:r[1],sub:'Workspace section',id:r[0]});dest.hidden=false;dest.innerHTML=`<p class="small">${results.length} matching entries · first 24 shown · Escape closes</p>`+results.slice(0,24).map(r=>`<button type="button" class="btn tiny" data-result="${esc(r.t)}" data-id="${esc(r.id)}">${esc(r.name)} <small>${esc(r.sub)}</small></button>`).join('')||'<p>No local matches.</p>'}
function redactShare(){return {format:'empowerment_share_candidate/1',created_local:stamp(),warning:'UNREVIEWED share candidate. Review free text, legal permissions, privacy, Indigenous data governance and consent before publishing.',projects:S.projects.map(p=>({id:p.id,title:p.title,domain:p.domain,scale:p.scale,place:'[REDACTED — add consented general region manually]',summary:'[REDACTED — provide non-sensitive problem statement manually]',outcome:'[REDACTED — provide approved measurable goal manually]',methods:p.methods||[],stage:'draft / user reported'})),method_descriptions:[],evidence:'[Omitted deliberately]',responsible_parties:'[Omitted deliberately]',private_notes:'[Omitted deliberately]',provenance:'Local candidate, not signed or independently timestamped'}}
