function valMethod(m){if(!m||typeof m!=='object')throw Error('Invalid method');const id=valId(m);if(!/^[a-z][a-z0-9_]{2,70}$/.test(id))throw Error('Method IDs must be lower-case underscores');let v={id,domain:valString(m,'domain',80,true),title:valString(m,'title',160,true),overview:valString(m,'overview',1200,true),action:valString(m,'action',1800,true),metric:valString(m,'metric',1200,true),risk:valString(m,'risk',1200,true)};v.readiness=valArray(m.readiness||[],15,'checks').map(z=>{if(typeof z!=='string'||z.length>240)throw Error('Invalid check');return z});return v}
function valProject(p){if(!p||typeof p!=='object')throw Error('Invalid project');const x={id:valId(p)};for(let k of ['title','domain','scale','place','audience','need','goal','constraints','owner','stage','created','updated'])x[k]=valString(p,k,k==='need'?2800: k==='constraints'?2200: k==='goal'?1800:210,['title','domain','place','need','goal'].includes(k));x.methods=valArray(p.methods||[],100,'project method selections').map(s=>{if(typeof s!=='string'||s.length>100)throw Error('Invalid method reference');return s});x.technologies=valArray(p.technologies||[],63,'technology selections').map(s=>{if(typeof s!=='string'||s.length>150)throw Error('Invalid technology reference');return s});return x}
