function valEcosystem(x){
 const blank={customModules:[],projectModules:{}};
 if(x===undefined||x===null)return blank;
 if(!x||typeof x!=='object'||Array.isArray(x))throw Error('Invalid ecosystem records');
 const checkIds=(items,max,label)=>valArray(items||[],max,label).map(id=>{
   if(typeof id!=='string'||!/^[a-z][a-z0-9_]{2,70}$/.test(id)||['__proto__','constructor','prototype'].includes(id))throw Error('Invalid '+label+' reference');return id;
 });
 const validateModule=m=>{
  if(!m||typeof m!=='object'||Array.isArray(m))throw Error('Invalid module');
  let v={id:valString(m,'id',72,true),title:valString(m,'title',160,true),version:valString(m,'version',32,true),domain:valString(m,'domain',80,true),description:valString(m,'description',1200,true),review:valString(m,'review',900,true),provenance:valString(m,'provenance',900,true),built_in:false};
  if(!/^[a-z][a-z0-9_]{2,70}$/.test(v.id)||!/^\d+\.\d+\.\d+$/.test(v.version))throw Error('Invalid module identifier/version');
  for(let k of ['method_ids','dependencies'])v[k]=checkIds(m[k],100,k);
  for(let k of ['requirements','roles','outputs'])v[k]=valArray(m[k]||[],25,k).map(z=>{if(typeof z!=='string'||z.length>250||!z.trim())throw Error('Invalid module '+k);return z});
  if(new Set(v.method_ids).size!==v.method_ids.length||new Set(v.dependencies).size!==v.dependencies.length||v.dependencies.includes(v.id))throw Error('Repeated or self-referential module IDs');
  return v;
 };
 blank.customModules=valArray(x.customModules||[],50,'custom modules').map(validateModule);
 if(new Set(blank.customModules.map(m=>m.id)).size!==blank.customModules.length)throw Error('Duplicate custom modules');
 const map=x.projectModules||{};
 if(!map||typeof map!=='object'||Array.isArray(map)||Object.keys(map).length>300)throw Error('Invalid project/module map');
 for(const [pid,refs] of Object.entries(map)){
  if(!/^[\w.:-]{2,130}$/.test(pid)||['__proto__','prototype','constructor'].includes(pid))throw Error('Invalid linked project ID');
  const values=checkIds(refs,60,'module assignments');if(new Set(values).size!==values.length)throw Error('Duplicate module assignment');blank.projectModules[pid]=values;
 }
 return blank;
}

/* V3: validated, inert innovation records; no executable content from JSON imports. */
function valInnovation(x){
 const blank={genomes:[],experiments:[]};
 if(x===undefined||x===null)return blank;
 if(!x||typeof x!=='object'||Array.isArray(x))throw Error('Invalid innovation records');
 function textRecord(obj,keys,required){
  if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('Invalid innovation record');
  const out={id:valId(obj)};
  for(const [k,limit] of keys)out[k]=valString(obj,k,limit,required.includes(k));
  return out;
 }
 blank.genomes=valArray(x.genomes||[],300,'innovation genomes').map(g=>{
  const v=textRecord(g,[['projectId',130],['title',160],['problem',2000],['mechanism',2400],['hypothesis',1800],['population',1000],['consent',1400],['metric',1000],['falsifier',1400],['stop',1400],['alternatives',1600],['owner',400],['status',40],['created',55],['updated',55]],['title','problem','mechanism','hypothesis','metric','falsifier','stop']);
  if(!['draft','review','pilot','stopped','completed'].includes(v.status))throw Error('Invalid genome status');return v;
 });
 blank.experiments=valArray(x.experiments||[],600,'experiments').map(e=>{
  const v=textRecord(e,[['genomeId',130],['projectId',130],['hypothesis',1800],['baseline',900],['comparator',900],['measure',900],['stop',900],['observation',1800],['interpretation',1800],['status',40],['date',55]],['genomeId','hypothesis','measure','stop']);
  if(!['planned','running','observed','stopped'].includes(v.status))throw Error('Invalid experiment status');return v;
 });
 for(const k of ['genomes','experiments'])if(new Set(blank[k].map(item=>item.id)).size!==blank[k].length)throw Error('Duplicate IDs in '+k);
 const genomeIds=new Set(blank.genomes.map(g=>g.id));if(blank.experiments.some(e=>!genomeIds.has(e.genomeId)))throw Error('Orphan experiment references a missing genome');
 return blank;
}
function validateFull(x){if(!x||typeof x!=='object'||Array.isArray(x)||!((x.format==='empowerment_foundry/1'&&x.schema===1)||(x.format==='empowerment_foundry/2'&&x.schema===2)))throw Error('Unsupported workspace format/version');let v=DEFAULT();for(let [k,max,fn] of [['projects',300,valProject],['evidence',1500,valEvidence],['pathways',1000,valPath],['scenarios',1200,valScenario],['customMethods',100,valMethod]]){v[k]=valArray(x[k],max,k).map(fn);if(new Set(v[k].map(z=>z.id)).size!==v[k].length)throw Error('Duplicate IDs in '+k)}v.fieldwork=valArray(x.fieldwork||[],300,'fieldwork').map(validateFieldwork);if(new Set(v.fieldwork.map(w=>w.id)).size!==v.fieldwork.length)throw Error('Duplicate fieldwork project IDs');if(v.fieldwork.some(w=>!v.projects.some(p=>p.id===w.id)))throw Error('Orphan fieldwork without a project');v.gates=Object.create(null);if(x.gates&&typeof x.gates==='object'&&!Array.isArray(x.gates)){for(let [pid,rec] of Object.entries(x.gates)){if(!/^[\w.:-]{2,130}$/.test(pid)||['__proto__','prototype','constructor'].includes(pid)||!rec||typeof rec!=='object')throw Error('Invalid gate records');const o={};for(let [gid,c] of Object.entries(rec)){if(!GATES.some(g=>g[0]===gid)||!c||!['not_assessed','documented','blocked'].includes(c.status))throw Error('Invalid gate status');o[gid]={status:c.status,note:valString(c,'note',1200),reference:valString(c,'reference',500),updated:valString(c,'updated',40)}}v.gates[pid]=o}}v.qa={};if(x.qa&&typeof x.qa==='object'&&!Array.isArray(x.qa)){for(let [i,c] of Object.entries(x.qa)){if(!/^\d{1,2}$/.test(i)||+i>=QA.length||!c||typeof c.checked!=='boolean')throw Error('Invalid QA record');v.qa[i]={checked:c.checked,note:valString(c,'note',360)}}}v.events=valArray(x.events||[],250,'events').map(e=>({id:valId(e),date:valString(e,'date',50),action:valString(e,'action',100),details:valString(e,'details',350)}));v.created=valString(x,'created',55);v.settings={theme:x.settings?.theme==='light'?'light':'dark',motion:x.settings?.motion===true,font:1};v.ecosystem=valEcosystem(x.ecosystem);v.innovation=valInnovation(x.innovation);return v}
async function previewFile(){const f=$('import-file').files?.[0];previewImport=null;$('import-merge').disabled=$('import-replace').disabled=true;$('exchange-diff').replaceChildren();if(!f)return say('import-report','Select a file first.');try{if(f.size>2*1024*1024)throw Error('Import exceeds 2 MB');const obj=JSON.parse(await f.text());let data,kind;if(obj.format==='empowerment_method_pack/1'){kind='methods';data=valArray(obj.methods,100,'methods').map(valMethod);if(new Set(data.map(x=>x.id)).size!==data.length)throw Error('Duplicate method IDs')}else{kind='full';data=validateFull(obj)}previewImport={kind,data,filename:f.name};const imported=kind==='methods'?data:data.projects,existing=new Set(kind==='methods'?methods().map(m=>m.id):S.projects.map(p=>p.id)),conflicts=imported.filter(x=>existing.has(x.id)),novel=imported.length-conflicts.length;say('import-report',`${kind==='methods'?'Method pack':'Full workspace'}: ${imported.length} primary records, ${novel} new, ${conflicts.length} conflicting IDs. File: ${f.name}. ${kind==='full'?'Source: '+obj.format+' (migrated to /2 on save). Field plans: '+data.fieldwork.length+'; module assignments: '+Object.keys(data.ecosystem.projectModules).length+'; genomes: '+data.innovation.genomes.length+'; experiments: '+data.innovation.experiments.length+'.':''} Data has not been merged or executed.`);$('import-merge').disabled=false;$('import-replace').disabled=kind==='methods';$('exchange-diff').innerHTML=`<div class="listcard"><strong>Preview differences</strong><p>New records: ${novel}; unchanged/potential conflicts: ${conflicts.length}. Merge never overwrites existing IDs.</p><p class="small">${esc(conflicts.slice(0,15).map(x=>x.id).join(', ')||'No conflicting primary IDs.')}</p></div>`;toast('Import shape validated. This is not authenticity or factual verification.')}catch(e){say('import-report','Import rejected: '+e.message);toast('Import rejected: '+e.message,true)}}
function mergeById(dst,src){let seen=new Set(dst.map(x=>x.id)),added=0,skipped=0;for(let x of src){if(seen.has(x.id)){skipped++;continue}dst.push(clone(x));seen.add(x.id);added++}return [added,skipped]}
async function importMerge(){
 if(!previewImport)return;
 try{
  const staged=clone(S),notes=[];
  if(previewImport.kind==='methods'){
   const defs=previewImport.data.filter(m=>!EMBED.methods.some(b=>b.id===m.id));
   const [a,b]=mergeById(staged.customMethods,defs);notes.push(`methods: ${a} added, ${b} conflicts skipped`);
  }else{
   const incoming=previewImport.data,previous=new Set(staged.projects.map(p=>p.id));
   for(const key of ['projects','evidence','pathways','scenarios','customMethods','fieldwork']){
    let records=incoming[key];
    if(key==='customMethods')records=records.filter(m=>!EMBED.methods.some(b=>b.id===m.id));
    if(key==='fieldwork')records=records.filter(w=>!previous.has(w.id)&&staged.projects.some(p=>p.id===w.id));
    const [added,skipped]=mergeById(staged[key],records);notes.push(`${key}: ${added} added, ${skipped} conflicts skipped`);
   }
   for(const [pid,g] of Object.entries(incoming.gates))if(!previous.has(pid)&&staged.projects.some(p=>p.id===pid)&&!staged.gates[pid])staged.gates[pid]=clone(g);
   for(const [idx,item] of Object.entries(incoming.qa))if(!staged.qa[idx])staged.qa[idx]=clone(item);
   const knownModules=new Set((window.FOUNDRY_REGISTRY?.modules||[]).map(m=>m.id));
   const incomingModules=incoming.ecosystem.customModules.filter(m=>!knownModules.has(m.id));
   const [added,skipped]=mergeById(staged.ecosystem.customModules,incomingModules);
   notes.push(`custom modules: ${added} added, ${skipped} conflicts skipped`);
   const validIds=new Set([...knownModules,...staged.ecosystem.customModules.map(m=>m.id)]);
   let assigned=0,unresolved=0;
   for(const [pid,ids] of Object.entries(incoming.ecosystem.projectModules)){
    if(previous.has(pid)||!staged.projects.some(p=>p.id===pid))continue;
    const valid=ids.filter(id=>validIds.has(id));unresolved+=ids.length-valid.length;
    if(!Object.prototype.hasOwnProperty.call(staged.ecosystem.projectModules,pid)){
     staged.ecosystem.projectModules[pid]=valid;assigned++;
    }
   }
   notes.push(`project assignments: ${assigned} added, ${unresolved} unresolved references excluded`);
   const knownGenomes=new Set(staged.innovation.genomes.map(g=>g.id));
   const genomeCandidates=incoming.innovation.genomes.filter(item=>!item.projectId||!previous.has(item.projectId));
   const acceptedGenomeIds=new Set(genomeCandidates.filter(g=>!knownGenomes.has(g.id)).map(g=>g.id));
   const [genomeAdded,genomeSkipped]=mergeById(staged.innovation.genomes,genomeCandidates);
   notes.push(`genomes: ${genomeAdded} added, ${genomeSkipped} conflicts skipped`);
   const experimentCandidates=incoming.innovation.experiments.filter(item=>acceptedGenomeIds.has(item.genomeId));
   const [experimentAdded,experimentSkipped]=mergeById(staged.innovation.experiments,experimentCandidates);
   notes.push(`experiments: ${experimentAdded} added, ${experimentSkipped} ID collisions, ${incoming.innovation.experiments.length-experimentCandidates.length} unsafe/conflicting-parent records skipped`);
   staged.events=[...new Map(staged.events.concat(incoming.events).map(e=>[e.id,e])).values()].slice(-250);
  }
  const valid=validateFull(staged);S=valid;log('validated_v3_merge',previewImport.filename);
  await persist();refresh();
  say('import-report','Version-aware, validated merge: '+notes.join('; ')+'. Existing project IDs retain their original specialized records. Export a new private backup.');
  previewImport=null;$('import-merge').disabled=$('import-replace').disabled=true;
  toast('Compatible records merged; conflicting records left unchanged.');
 }catch(e){say('import-report','Merge refused before changing state: '+e.message);toast('Merge rejected; nothing applied.',true)}
}
