/* === UNIFIED PROTOCOL INTEGRATION: source-based data and shared Foundry state === */
const PROTOCOL_MODELS={
food:{fields:[['area','Cultivated area','m²',30,0,100000],['yield','Observed or assumed usable yield','kg/m² per season',2,0,1000],['edible','Edible fraction','fraction 0–1',.85,0,1],['serving','Mass per produce serving','kg/serving',.08,.001,10]],key:'yield',explain:'The yield input is a user assumption or locally measured value, not a universal crop benchmark.',fn:v=>({value:v.area*v.yield*v.edible/v.serving,unit:'illustrative produce servings',extra:`Edible harvest: ${fmt(v.area*v.yield*v.edible)} kg. This is a mass-equivalence, NOT nutritional adequacy, dietary diversity, guaranteed harvest or proof of better access.`,formula:'area (m²) × yield (kg/m²) × edible fraction ÷ serving mass (kg/serving)'})},
energy:{fields:[['capacity','Battery nameplate capacity','Wh',1500,.001,1e9],['usable','Fraction available after reserves','fraction 0–1',.8,0,1],['load','Average continuous load','W',150,.001,1e8],['efficiency','System discharge efficiency','fraction 0–1',.88,0,1]],key:'load',explain:'This is an idealized electrical energy balance, not equipment sizing.',fn:v=>({value:v.capacity*v.usable*v.efficiency/v.load,unit:'illustrative hours',extra:'Does not assess load surge, inverter ratings, charge state accuracy, ambient temperature, battery damage, fire risk, or medical-device reliability. Use a qualified professional for critical loads.',formula:'capacity (Wh) × usable fraction × efficiency ÷ load (W)'})},
repair:{fields:[['replacement','Replacement purchase cost','local currency',240,0,1e9],['disposal','Disposal and acquisition costs','local currency',15,0,1e9],['repair','Repair and parts cost','local currency',110,0,1e9],['transport','Travel, downtime and other repair costs','local currency',20,0,1e9]],key:'repair',explain:'Comparable service life, function, warranties and safety must be checked separately.',fn:v=>({value:(v.replacement+v.disposal)-(v.repair+v.transport),unit:'local currency difference (positive favors repair)',extra:'Illustrative purchase-cost comparison only. It excludes future failures, operating efficiency, discount rates and life-cycle environmental impacts.',formula:'(replacement + disposal) − (repair + repair travel/downtime)'})},
ecology:{fields:[['planted','Originally tagged individuals','count',100,1,1e7],['alive','Still alive on fixed census date','count',72,0,1e7],['missing','Missing or unverified tags','count',6,0,1e7]],key:'alive',explain:'Unknown tagged individuals cannot silently be excluded from the denominator.',fn:v=>{if(v.alive+v.missing>v.planted)throw Error('Alive + missing exceeds original tagged plants. Recheck census.');return {value:100*v.alive/v.planted,unit:'% confirmed survival (conservative)',extra:`${fmt(v.missing,0)} individuals remain unverified. If all missing prove alive, upper descriptive bound is ${fmt(100*(v.alive+v.missing)/v.planted)}%. Survival alone does not measure ecosystem recovery.`,formula:'100 × confirmed live / originally tagged'}}}
};
function computeProtocolModel(model,v,sensitivity){const m=PROTOCOL_MODELS[model];for(const [id,label,unit,_,min,max] of m.fields){if(!Number.isFinite(v[id])||v[id]<min||v[id]>max)throw Error(label+' must be between '+min+' and '+max)}const middle=m.fn(v);const key=m.key,lower={...v,[key]:v[key]*(1-sensitivity)},upper={...v,[key]:v[key]*(1+sensitivity)};const results=[m.fn(lower).value,m.fn(upper).value];return {...middle,min:Math.min(...results),max:Math.max(...results)}}
const RESEARCH_AXES=[
['Need and population','Who defines the problem, whose needs or rights are missing, and what is the baseline?','The registry specifies a candidate problem, not a verified local baseline. Interview affected people with consent; disaggregate access only where privacy permits.'],
['Evidence strength','Which exact population, study design, comparator and measured outcomes support the proposal?','Curated references describe relevant research or practice guidance. No source in this file alone validates this specific local intervention. Read methods and estimate applicability.'],
['Mechanism and alternatives','By what mechanism could this work, and which less complex alternatives deserve comparison?','The domain registry supplies a plausible mechanism and a competing explanation. Compare service delivery, affordability and maintenance—not just technology.'],
['Safety and governance','Who bears risk, who can refuse, and what permits or expert review are needed?','Use the domain safeguard and local rules before starting. Stop where qualified supervision or permission is required.'],
['Outcome measurement','What would count as a meaningful outcome, measured when and how?','Choose one primary metric, lock its unit and denominator before work, record missingness and adverse events. Tasks completed are not outcomes.'],
['Causal inference','What other change could explain the observation and what comparison is feasible?','A before–after difference is descriptive only. Consider seasonality, self-selection, displacement, secular trends and comparator integrity.'],
['Falsification','What evidence would make us abandon or alter the proposal?','Specify a stop rule for harm, unacceptable burden or a measured failure to achieve minimum meaningful improvement. Record negative findings.'],
['Equity and scalability','Who might be excluded if scaled and who pays long-run upkeep?','Audit participation barriers, land and data rights, costs, staff capacity and maintenance. Replicate independently before claiming transferability.']
];
function makeProtocolResearchBundle(engineId,challenge,audience,boundary,mode){const e=PROTOCOL_BY_ID[engineId]||PROTOCOL_ENGINES[0],refs=e.sources.map(id=>PROTOCOL_SOURCE_BY_ID[id]).filter(Boolean),claim=challenge.trim()||e.problem,questions=RESEARCH_AXES.map(([name,question,answer],i)=>({name,question,answer:i===2?`Hypothesized mechanism: ${e.mechanism} Competing account: ${e.counter} ${answer}`:i===3?`${e.critical} Explicit boundary: ${boundary||'Ask participants to define the boundary.'} ${answer}`:i===4?`Candidate metric: ${e.metric[0][1]} (${e.metric[0][2]}). ${answer}`:answer,unresolved:i===0?'Actual beneficiary priorities, denominator and baseline are unknown.':i===1?'Study quality and locally applicable effect sizes need independent examination.':i===3?'Applicable permits and expert assessment have not been checked.':i===4?'Baseline distribution, precision and minimally meaningful effect are unmeasured.':'Requires a local, consented investigation.'}));const steps=['Discover: search up-to-date primary studies and policy guidance, log search dates and exact inclusion criteria.','Challenge: construct the strongest credible null hypothesis, non-technical alternative and failure path.','Co-design: consult affected people, rights holders, experienced practitioners and those likely to be excluded.','Prototype: specify one low-risk pilot, controls, stopping conditions, sample and accessible fallback.','Verify: freeze the indicator and method, log observations and adverse effects, invite independent review.','Transfer: release only licensed, permissioned, de-identified material; test in another context before scaling.'];const promptChain=[
`DISCOVER | Date-check the literature. Domain: ${e.name}. Problem: ${claim}. Decision-makers: ${audience}. Find 2024–2026+ systematic reviews, registered trials, datasets, relevant standards and primary studies. Search beyond English where feasible. Produce a deduplicated evidence table containing title, DOI, publication date, sample/population, comparator, outcome, effect/uncertainty, limitations, license, geographic transferability and any retractions. Do not fabricate citations. Start with source IDs: ${e.sources.join(', ')}; verify each original. Identify major missing evidence.`,
`ADVERSARIAL VALIDATION | Challenge the proposal "${claim}" without presuming success. Identify at least four plausible alternative explanations, confounders, publication/selection bias, negative effects and opportunity costs. Compare the non-technological alternative. Write explicit falsification and stopping criteria. Safety boundary: ${boundary}.`,
`CO-DESIGN & PILOT | Design a voluntary ${e.name} pilot for ${audience}. Translate expert science into plain-language steps; specify local permissions, risk owners, safeguarding, accessibility, culturally appropriate co-governance, maintenance, costs and alternatives. Starting pilot: ${e.pilot} Define a realistic control or comparison where ethical.`,
`PREREGISTER & VERIFY | Primary outcome metric: ${e.metric[0][1]} in ${e.metric[0][2]}. Choose a meaningful target with justification, sampling frame, baseline, instrument calibration, follow-up, missingness protocol and honest uncertainty. Avoid claiming causation from a before–after observation. Report nulls, adverse effects, subgroup burdens and data-quality flags.`,
`INDEPENDENT REVIEW | Have qualified domain practitioners and affected participants audit factual accuracy, measurement reproducibility, permissions, consent, disparate harms, source links and conflicts of interest. State unresolved risks and whether evidence justifies continuing, revising or stopping. Do not issue certification from model output.`,
`REPLICATION & TRANSFER | Package methods, schema, provenance, dependency versions, instructions, safety boundaries, negative findings and an accessible offline copy. Respect open-source licenses, Indigenous data sovereignty, personal privacy and permission revocation BEFORE transfer. Compare replication outcome across new sites and document non-transferable conditions.`
];const lines=[`FOSTER + NAVI · EVIDENCE-BOUNDED RESEARCH BRIEF · ${new Date().toISOString().slice(0,10)}`,`Snapshot: ${PROTOCOL_SNAPSHOT} · Domain: ${e.name} · Mode: ${mode.toUpperCase()}`,`Research challenge: ${claim}`,`Intended participants: ${audience}`,`Safety/consent boundary: ${boundary}`,`KNOWN FROM CURATED PROTOCOL_SNAPSHOT (NOT A LOCAL TRIAL): ${e.research}`,`WORKING MECHANISM: ${e.mechanism}`,`COUNTERARGUMENT: ${e.counter}`,`SAFE START: ${e.pilot}`,`NONNEGOTIABLE: ${e.critical}`,...questions.map((x,i)=>`${i+1}. ${x.name}\nQUESTION: ${x.question}\nWORKING ANSWER: ${x.answer}\nUNRESOLVED: ${x.unresolved}`),`CANDIDATE MEASURES: ${e.metric.map(m=>m[1]+' ['+m[2]+', desired '+m[3]+']').join('; ')}`,`REVIEWED REFERENCE POINTERS (verify current originals):`,...refs.map(s=>`${s.id} ${s.org} ${s.year}: ${s.title}\n${s.url}\nLIMITATION: ${s.limit}`),`PROCEDURE:`,...steps.map((s,i)=>`${i+1}. ${s}`),'PROVENANCE STATUS: Generated deterministically from locally embedded summaries and user input. No live search, AI inference service, statistical analysis, expert certification or field validation.'];return {e,claim,questions,steps,promptChain,refs,text:lines.join('\n\n')}}
/* PROTOCOL DATA: original source records embedded verbatim as JSON, not claimed current. */
const PROTOCOL_DATA=JSON.parse(document.getElementById('protocol-snapshot').textContent);
const PROTOCOL_SNAPSHOT=PROTOCOL_DATA.snapshot;
const PROTOCOL_ENGINES=PROTOCOL_DATA.engines;
const PROTOCOL_BY_ID=Object.fromEntries(PROTOCOL_ENGINES.map(x=>[x.id,x]));
const PROTOCOL_SOURCE_BY_ID=Object.fromEntries(PROTOCOL_DATA.sources.map(x=>[x.id,x]));
const PROTOCOL_DOMAINS={food:'food',skills:'careers',resilience:'water',education:'education',repair:'repair',navigator:'civic',evidence:'science',ecology:'restoration',exchange:'governance',foundry:'digital'};
const PROTOCOL_METHODS={food:'food_01',skills:'careers_01',resilience:'water_03',education:'education_01',navigator:'civic_02',evidence:'science_01',ecology:'restoration_01',exchange:'governance_03',foundry:'digital_01'};
let activeProtocolResearch=null,activeProtocolModel=null,legacyCandidate=null;
function requiredLegacyString(o,k,max=3000){if(typeof o?.[k]!=='string'||o[k].length>max)throw Error('Invalid legacy '+k);return o[k]}
function boundedLegacyString(x,max){if(x===undefined||x===null)return '';if(typeof x!=='string'||x.length>max)throw Error('Invalid legacy text field');return x}
function protocolNumber(v,nullable=false){if((v===null||v===''||v===undefined)&&nullable)return null;if(typeof v!=='number'||!Number.isFinite(v)||Math.abs(v)>1e12)throw Error('Invalid numeric field');return v}
function validateFieldwork(w){
 if(!w||typeof w!=='object'||Array.isArray(w))throw Error('Invalid fieldwork');
 const id=valId(w),engine=requiredLegacyString(w,'engine',70);
 if(!PROTOCOL_BY_ID[engine])throw Error('Unknown Protocol engine');
 const metrics=PROTOCOL_BY_ID[engine].metric;
 const metric=requiredLegacyString(w,'metric',100);
 if(!metrics.some(m=>m[0]===metric))throw Error('Unrecognized engine metric');
 const rawTasks=valArray(w.tasks,35,'fieldwork tasks');
 const tasks=rawTasks.map(t=>{if(!t||typeof t!=='object'||typeof t.done!=='boolean')throw Error('Invalid fieldwork task');return {label:requiredLegacyString(t,'label',240),done:t.done}});
 const obs=valArray(w.observations,500,'observations').map(o=>{
  if(!o||typeof o!=='object')throw Error('Invalid observation');
  return {id:valId(o),date:requiredLegacyString(o,'date',50),value:protocolNumber(o.value,true),unit:requiredLegacyString(o,'unit',80),method:requiredLegacyString(o,'method',420),note:boundedLegacyString(o.note,1000)};
 });
 if(new Set(obs.map(o=>o.id)).size!==obs.length)throw Error('Duplicate observation ID');
 const budget=protocolNumber(w.budget),baseline=protocolNumber(w.baseline,true),target=protocolNumber(w.target,true);
 if(budget<0)throw Error('Budget must not be negative');
 const window=protocolNumber(w.window);if(window<1||window>3660)throw Error('Invalid review window');
 return {id,engine,metric,budget,window,baseline,target,tasks,observations:obs,context:boundedLegacyString(w.context,1300),created:boundedLegacyString(w.created,55)};
}
function protocolDefaultField(p,engineId){const e=PROTOCOL_BY_ID[engineId];if(!e)throw Error('Unknown engine');return {id:p.id,engine:e.id,metric:e.metric[0][0],budget:0,window:90,baseline:null,target:null,tasks:e.tasks.map(label=>({label,done:false})),observations:[],context:p.constraints||'',created:stamp()}}
function refreshProtocolUI(){if(!$('protocol-search'))return;const project=$('field-project'),prior=project.value;project.replaceChildren(new Option('Select project',''));for(const p of S.projects)project.add(new Option(p.title+' · '+p.place,p.id));project.value=S.projects.some(p=>p.id===prior)?prior:S.projects.some(p=>p.id===selectedProject)?selectedProject:'';renderProtocolEngines();renderProtocolSources();renderProtocolMethods();renderFieldwork()}
function renderProtocolEngines(){const q=cap($('protocol-search').value),items=PROTOCOL_ENGINES.filter(e=>!q||JSON.stringify(e).toLowerCase().includes(q));say('protocol-count',items.length+' of 10 detailed source-based engines');$('protocol-results').innerHTML=items.map(e=>{
 const refs=e.sources.map(id=>PROTOCOL_SOURCE_BY_ID[id]).filter(Boolean);
 return `<article class="panel protocol-card"><span class="eyebrow">${esc(e.icon)} ${esc(e.id)} · ORIGINAL PROTOCOL</span><h3>${esc(e.name)}</h3><p>${esc(e.subtitle)}</p><p><strong>Observed need to investigate:</strong> ${esc(e.problem)}</p><details><summary>Full evidence, mechanism, implementation and safeguards</summary><div class="detail"><p><strong>Mechanism:</strong> ${esc(e.mechanism)}</p><p><strong>Dated research synthesis:</strong> ${esc(e.research)}</p><p><strong>Science / evaluation:</strong> ${esc(e.science)}</p><p><strong>Accessible pilot:</strong> ${esc(e.pilot)}</p><p><strong>Competing account:</strong> ${esc(e.counter)}</p><div class="callout warn"><strong>Critical boundary:</strong> ${esc(e.critical)}</div><h4>Candidate indicators</h4><ul>${e.metric.map(m=>`<li>${esc(m[1])} (${esc(m[2])}); desired direction ${esc(m[3])}</li>`).join('')}</ul><h4>Original seven-step field checklist</h4><ol>${e.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h4>Linked source records</h4><ul>${refs.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.id)} · ${esc(s.org)} (${s.year}): ${esc(s.title)}</a><p class="small">${esc(s.limit)}</p></li>`).join('')}</ul><p class="small">Proposed cross-engine dependencies: ${esc(e.links.join(', '))}. Conceptual links, not demonstrated causal effects.</p></div></details><div class="protocol-quick"><button class="btn tiny" data-protocol-create="${esc(e.id)}" type="button">Create project from engine</button><button class="btn tiny" data-protocol-research="${esc(e.id)}" type="button">Research this engine</button></div></article>`
 }).join('')||'<div class="panel"><p>No engines match. Clear your search.</p></div>'}
function renderProtocolSources(){const q=cap($('protocol-source-search').value),sources=PROTOCOL_DATA.sources.filter(s=>!q||JSON.stringify(s).toLowerCase().includes(q));$('protocol-sources').innerHTML=sources.map(s=>`<article class="listcard"><span class="badge">${esc(s.id)} · ${s.year} · ${esc(s.domain)}</span><h3>${esc(s.title)}</h3><p>${esc(s.org)}</p><p class="small">${esc(s.take)}</p><p class="small"><strong>Limit:</strong> ${esc(s.limit)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open original source (internet required)</a></article>`).join('')||'<p>No sources match.</p>'}
function renderProtocolMethods(){
 $('protocol-evaluation').innerHTML=PROTOCOL_DATA.methods.map(m=>`<article class="listcard"><h3>${esc(m[0])}</h3><p>${esc(m[1])}</p><p class="small">${esc(m[2])}</p></article>`).join('');
 $('protocol-glossary').innerHTML=PROTOCOL_DATA.glossary.map(([name,meaning])=>`<article class="listcard"><h3>${esc(name)}</h3><p>${esc(meaning)}</p></article>`).join('');
}
function setProtocolEngine(id){for(const sel of ['protocol-engine-select','pr-engine','field-engine'])$(sel).value=id}
function generateProtocolResearch(ev){if(ev)ev.preventDefault();const id=$('pr-engine').value,e=PROTOCOL_BY_ID[id];if(!e)return toast('Choose research engine first.',true);let b=makeProtocolResearchBundle(id,txt($('pr-challenge').value),txt($('pr-audience').value),txt($('pr-boundary').value),$('pr-mode').value);activeProtocolResearch=b;$('pr-output').value=b.text;$('pr-prompts').innerHTML=b.promptChain.map((p,i)=>`<details><summary>Prompt ${i+1}: ${['Discover','Challenge','Co-design','Verify','Review','Transfer'][i]}</summary><div class="detail"><p class="small">Copy/export for an independently selected research tool; no source results were fetched.</p><pre>${esc(p)}</pre><button type="button" class="btn tiny" data-prompt-copy="${i}">Copy this prompt</button></div></details>`).join('');say('pr-status','Generated locally from the dated Protocol snapshot. The brief is editable and not saved to your project unless exported.');}
function renderProtocolModelInputs(){const m=PROTOCOL_MODELS[$('pm-type').value];$('pm-fields').innerHTML=m.fields.map(([id,label,unit,value,min,max])=>`<div class="field"><label for="pm_${id}">${esc(label)} <small>(${esc(unit)})</small></label><input id="pm_${id}" type="number" min="${min}" max="${max}" step="any" value="${value}" required></div>`).join('');activeProtocolModel=null;say('pm-result','Replace example inputs with verified local quantities; then calculate.')}
function runProtocolModel(ev){if(ev)ev.preventDefault();const type=$('pm-type').value,m=PROTOCOL_MODELS[type];try{const v={};for(const field of m.fields){const input=$('pm_'+field[0]);if(!input.value.trim()||!input.checkValidity())throw Error('Invalid input: '+field[1]);v[field[0]]=Number(input.value)}const sensitivity=Number($('pm-sensitivity').value)/100;const result=computeProtocolModel(type,v,sensitivity);activeProtocolModel={format:'empowerment_protocol_model/1',source_snapshot:PROTOCOL_SNAPSHOT,generated_local:stamp(),model:type,inputs:v,sensitivity,result,assumptions:m.explain,warning:'Illustrative dimensional arithmetic, not a forecast or approval.'};$('pm-result').innerHTML=`<h3>${esc(fmt(result.value))} ${esc(result.unit)}</h3><p><strong>Equation:</strong> ${esc(result.formula)}</p><p><strong>One-factor sensitivity, not statistical confidence:</strong> ${esc(fmt(result.min))} to ${esc(fmt(result.max))} ${esc(result.unit)}</p><p>${esc(result.extra)}</p><p class="small">${esc(m.explain)}</p>`;}catch(e){activeProtocolModel=null;say('pm-result','Calculation rejected: '+e.message)}}
function renderFieldwork(){const p=P($('field-project').value),w=p&&S.fieldwork.find(w=>w.id===p.id);if(!p){say('field-status','Create a Foundry project first.');$('field-detail').innerHTML='<p class="small">Choose a project to create its field checklist.</p>';return}if(!w){say('field-status','No Protocol field plan attached to '+p.title+'. Choose an engine and attach.');$('field-detail').innerHTML='<p class="small">Engine attachment uses the existing project record and keeps independent measurement logs. The original project remains editable.</p>';return}const e=PROTOCOL_BY_ID[w.engine],m=e.metric.find(x=>x[0]===w.metric)||e.metric[0];$('field-engine').value=w.engine;say('field-status',`${p.title} · ${e.name} · ${w.tasks.filter(t=>t.done).length}/${w.tasks.length} documented steps · ${w.observations.length} observations`);const observations=w.observations.map(o=>`<li><strong>${esc(o.date.slice(0,10))}</strong> · ${o.value===null?'qualitative only':esc(fmt(o.value))+' '+esc(o.unit)} · ${esc(o.method)}${o.note?'<p>'+esc(o.note)+'</p>':''}</li>`).join('')||'<li>No observations yet.</li>';let first=w.observations.find(x=>x.value!==null),last=w.observations.filter(x=>x.value!==null).at(-1),difference='At least two comparable numeric measurements are needed.';if(first&&last&&first!==last){difference=first.unit===last.unit?`${fmt(first.value)} → ${fmt(last.value)} ${esc(first.unit)}: descriptive difference ${fmt(last.value-first.value)}. This does not prove causation.`:'Units differ: no valid direct comparison. Record consistent units and denominators.'}
$('field-detail').innerHTML=`<h3>${esc(p.title)} · ${esc(e.name)}</h3><p>${esc(p.need)}</p><p class="small">Metric: ${esc(m[1])} (${esc(m[2])}); chosen direction ${esc(m[3])}.</p><div class="protocol-column"><div><label for="field-budget">Available budget (local currency units)</label><input id="field-budget" type="number" min="0" step="any" value="${w.budget}"></div><div><label for="field-window">Review window (days)</label><input id="field-window" type="number" min="1" max="3660" step="1" value="${w.window}"></div><div><label for="field-baseline">Baseline (optional)</label><input id="field-baseline" type="number" step="any" value="${w.baseline??''}"></div><div><label for="field-target">Proposed target (optional)</label><input id="field-target" type="number" step="any" value="${w.target??''}"></div></div><div class="protocol-quick"><button type="button" class="btn" id="field-metadata-save">Save budget, baseline and target</button></div><h3>Seven-stage checklist</h3><div>${w.tasks.map((t,i)=>`<div class="protocol-item ${t.done?'completed':''}"><label><input type="checkbox" data-field-task="${i}" ${t.done?'checked':''}><span class="task-name">${esc(t.label)}</span></label></div>`).join('')}</div><p class="small">Completion is self-reported process documentation, not evidence of resulting benefit.</p><h3>Measurement and learning log</h3><form class="formgrid" id="field-obs-form"><div class="field"><label for="field-obs-value">Observed value (optional)</label><input id="field-obs-value" type="number" step="any"></div><div class="field"><label for="field-obs-unit">Unit</label><input id="field-obs-unit" maxlength="80" required value="${esc(m[2])}"></div><div class="field full"><label for="field-obs-method">Method, instrument, denominator and uncertainty</label><input id="field-obs-method" required maxlength="420" placeholder="What was actually measured and how?"></div><div class="field full"><label for="field-obs-note">Limitations, adverse findings or qualitative observation</label><textarea id="field-obs-note" maxlength="1000"></textarea></div><button type="submit" class="btn primary">Record observation</button></form><div class="callout"><h3>Descriptive comparison</h3><p>${difference}</p><p class="small">Baseline recorded in plan: ${w.baseline===null?'not entered':fmt(w.baseline)}; proposed target: ${w.target===null?'not entered':fmt(w.target)}; target is not an observed outcome.</p></div><h3>Logged observations</h3><ol>${observations}</ol>`}
function startFieldwork(){const p=P($('field-project').value),engine=$('field-engine').value;if(!p)return toast('Choose a project first.',true);const existing=S.fieldwork.find(x=>x.id===p.id);if(existing){if(existing.engine!==engine)return toast('An engine is already attached. Export a backup and use a separate project to change engines without losing its field history.',true);return toast('Field plan already attached; existing tasks and measurements preserved.')}if(S.fieldwork.length>=300)return toast('Fieldwork capacity reached. Export first.',true);S.fieldwork.push(validateFieldwork(protocolDefaultField(p,engine)));log('protocol_fieldwork_started',p.id+' '+engine);persist();renderFieldwork();toast('A seven-step, measured project plan is attached.');}
function saveFieldMetadata(){let w=S.fieldwork.find(x=>x.id===$('field-project').value);if(!w)return;try{let budget=Number($('field-budget').value),window=Number($('field-window').value);if(!Number.isFinite(budget)||budget<0||budget>1e12)throw Error('Budget must be nonnegative and finite');if(!Number.isInteger(window)||window<1||window>3660)throw Error('Review window must be 1–3660 whole days');const readOpt=id=>{let s=$(id).value.trim();if(s==='')return null;let n=Number(s);if(!Number.isFinite(n)||Math.abs(n)>1e12)throw Error('Invalid baseline or target');return n};w.budget=budget;w.window=window;w.baseline=readOpt('field-baseline');w.target=readOpt('field-target');persist();renderFieldwork();toast('Field plan details saved.')}catch(e){toast(e.message,true)}}
function saveObservation(ev){ev.preventDefault();let w=S.fieldwork.find(x=>x.id===$('field-project').value);if(!w)return;if(w.observations.length>=500)return toast('500-observation limit; export backup first.',true);let s=$('field-obs-value').value.trim(),value=s===''?null:Number(s),unit=txt($('field-obs-unit').value),method=txt($('field-obs-method').value);if(value!==null&&(!Number.isFinite(value)||Math.abs(value)>1e12))return toast('Enter a finite measured number.',true);if(!unit||!method)return toast('Unit and method required.',true);w.observations.push({id:uid(),date:stamp(),value,unit:unit.slice(0,80),method:method.slice(0,420),note:$('field-obs-note').value.slice(0,1000)});log('protocol_observation',w.id);persist();renderFieldwork();toast('Observation saved, unverified.');}
function protocolLegacyParse(x){if(!x||typeof x!=='object'||Array.isArray(x)||x.schema!==1||x.app!=='Foster + Navi Empowerment Protocol'||!Array.isArray(x.projects)||!Array.isArray(x.evidence)||x.projects.length>200||x.evidence.length>500)throw Error('Unsupported original Protocol backup');const projects=[],fieldwork=[],evidence=[];for(const r of x.projects){if(!r||typeof r!=='object'||!PROTOCOL_BY_ID[r.engine])throw Error('Unrecognized legacy engine');let original=requiredLegacyString(r,'id',100);if(!/^[a-zA-Z0-9_-]{5,100}$/.test(original))throw Error('Invalid original project ID');const id='legacy_'+original,e=PROTOCOL_BY_ID[r.engine],metric=e.metric.find(m=>m[0]===r.metric)||e.metric[0];if(!Array.isArray(r.tasks)||r.tasks.length>35||!Array.isArray(r.observations)||r.observations.length>500)throw Error('Oversized legacy project');const tasks=r.tasks.map(t=>({label:requiredLegacyString(t,'label',240),done:t.done===true}));const observations=r.observations.map(o=>({id:valId({id:'legacy_'+requiredLegacyString(o,'id',100)}),date:boundedLegacyString(o.date,50),value:protocolNumber(o.value,true),unit:boundedLegacyString(o.unit,80),method:boundedLegacyString(o.method,420),note:boundedLegacyString(o.note,1000)}));let title=boundedLegacyString(r.title,120)||'Untitled imported Protocol project',need=boundedLegacyString(r.problem,1600),context=boundedLegacyString(r.context,1300),created=boundedLegacyString(r.created,55)||stamp();const p={id,title,domain:PROTOCOL_DOMAINS[r.engine],scale:boundedLegacyString(r.scale,120)||'Imported legacy scope',place:'Location not recorded in original Protocol',audience:'Not recorded in legacy file',need:need||'Original problem statement absent or redacted; restore from private backup if possible.',goal:metric[1]+' ('+metric[2]+'); target proposed, not achieved.',constraints:context,owner:'',stage:'Research',methods:PROTOCOL_METHODS[r.engine]?[PROTOCOL_METHODS[r.engine]]:[],technologies:[],created,updated:stamp()};projects.push(valProject(p));fieldwork.push(validateFieldwork({id,engine:r.engine,metric:metric[0],budget:protocolNumber(r.budget??0),window:protocolNumber(r.window??90),baseline:protocolNumber(r.baseline,true),target:protocolNumber(r.target,true),tasks,observations,context,created}));}
 for(const e of x.evidence){const id='legacy_'+requiredLegacyString(e,'id',100);const source=boundedLegacyString(e.url,1100),quality=boundedLegacyString(e.quality,100),claim=boundedLegacyString(e.claim,1200),limits=boundedLegacyString(e.limits,1200);evidence.push(valEvidence({id,projectId:'',claim:claim||'[Redacted evidence note: no original text]',type:boundedLegacyString(e.type,80)||'Imported note',status:'Not reviewed',source:(source+' '+quality).slice(0,700),limit:limits||'Original limitations absent or redacted; requires reassessment.',falsifier:'',date:boundedLegacyString(e.date,35)}))}
 if(new Set(projects.map(p=>p.id)).size!==projects.length||new Set(evidence.map(e=>e.id)).size!==evidence.length)throw Error('Duplicate legacy identifiers');return {projects,fieldwork,evidence};}
async function previewLegacy(){const f=$('legacy-file').files?.[0];legacyCandidate=null;$('legacy-merge').disabled=true;if(!f)return say('legacy-report','Select a JSON file first.');try{if(f.size>2*1024*1024)throw Error('File over 2 MB');let x=JSON.parse(await f.text());let data=protocolLegacyParse(x);let conflicts=data.projects.filter(p=>S.projects.some(t=>t.id===p.id)).map(p=>p.id),novel=data.projects.length-conflicts.length;legacyCandidate={data,filename:f.name,conflicts};say('legacy-report',`${data.projects.length} valid original projects; ${novel} new, ${conflicts.length} conflicting IDs; ${data.fieldwork.length} field plans; ${data.evidence.length} notes. No data changed yet.`);$('legacy-diff').innerHTML=`<div class="listcard"><h3>Preserved mapping</h3><p>Original Protocol IDs gain a legacy_ prefix. Full task state, measurement values, units, methods, notes and selected metric are carried into shared Foundry fieldwork. Original evidence notes are separate, not falsely assigned to a project. The original file contains no project place field; import labels the location as not recorded. The source engine ID is preserved even where domains are grouped.</p><p><strong>Conflicting project IDs:</strong> ${esc(conflicts.slice(0,10).join(', ')||'none')}.</p></div>`;$('legacy-merge').disabled=false;}catch(e){say('legacy-report','Legacy preview rejected: '+e.message);toast('Legacy validation failed; no data changed.',true)}}
async function mergeLegacy(){if(!legacyCandidate)return;const {data,filename}=legacyCandidate;let pAdded=0,eAdded=0;const available=300-S.projects.length;if(data.projects.filter(p=>!P(p.id)).length>available)return toast('Not enough project capacity; export/archive projects first.',true);if(S.evidence.length+data.evidence.filter(e=>!S.evidence.some(o=>o.id===e.id)).length>1500)return toast('Evidence capacity reached; back up before merging.',true);const allowed=new Set();for(let p of data.projects){if(!P(p.id)){S.projects.push(p);allowed.add(p.id);pAdded++}}
 for(let w of data.fieldwork){if(allowed.has(w.id)&&!S.fieldwork.some(z=>z.id===w.id))S.fieldwork.push(w)}for(let e of data.evidence){if(!S.evidence.some(z=>z.id===e.id)){S.evidence.push(e);eAdded++}}
 log('validated_legacy_protocol_merge',filename);await persist();selectedProject=S.projects.at(-1)?.id||selectedProject;refresh();say('legacy-report',`Merged ${pAdded} new projects and ${eAdded} distinct evidence notes. Conflicting project IDs were skipped with their fieldwork. Export a unified private backup now; your original JSON was not changed.`);legacyCandidate=null;$('legacy-merge').disabled=true;toast('Legacy migration completed. Export a unified backup.');}
function runMergedTests(){let checks=[];function test(name,fn){try{fn();checks.push('PASS · '+name)}catch(e){checks.push('FAIL · '+name+' · '+e.message)}}test('Ten unique Protocol engines',()=>{if(PROTOCOL_ENGINES.length!==10||new Set(PROTOCOL_ENGINES.map(e=>e.id)).size!==10)throw Error('Registry mismatch')});test('Twenty-two retained research sources',()=>{if(PROTOCOL_DATA.sources.length!==22)throw Error('Source count mismatch')});test('Every engine has seven tasks and valid source pointers',()=>{if(PROTOCOL_ENGINES.some(e=>e.tasks.length!==7||e.sources.some(id=>!PROTOCOL_SOURCE_BY_ID[id])))throw Error('Source pointer or task failure')});test('Food model 480 produce-serving equivalents',()=>{if(computeProtocolModel('food',{area:30,yield:2,edible:.8,serving:.1},0).value!==480)throw Error('Unit arithmetic mismatch')});test('Electrical model 8 hours',()=>{if(computeProtocolModel('energy',{capacity:1000,usable:.8,load:100,efficiency:1},0).value!==8)throw Error('Unit mismatch')});test('Impossible ecology census rejected',()=>{let rejected=false;try{computeProtocolModel('ecology',{planted:5,alive:4,missing:3},0)}catch{rejected=true}if(!rejected)throw Error('Accepted impossible count')});test('Research includes 8 questions and 6 prompts',()=>{const b=makeProtocolResearchBundle('food','Test','People','Consent','doctoral');if(b.questions.length!==8||b.promptChain.length!==6)throw Error('Research structure broken')});test('Shared backup fieldwork validation',()=>{const x=validateFull(clone(S));if(x.fieldwork.length!==S.fieldwork.length)throw Error('Data lost in validation')});test('Safe renderer encodes HTML',()=>{if(esc('<img src=x onerror=alert(1)>').includes('<img'))throw Error('Unsafe escape')});test('No duplicate fieldwork IDs',()=>{if(new Set(S.fieldwork.map(x=>x.id)).size!==S.fieldwork.length)throw Error('Duplicate field plan')});let passed=checks.filter(x=>x.startsWith('PASS')).length;say('merge-test-report',`${passed}/${checks.length} pure-function checks passed. This is not a full browser, security or accessibility audit.\n`+checks.join('\n'));return {passed,total:checks.length}}
function setupProtocolUI(){
 const map=[['protocol-engine-select','Choose engine'],['pr-engine','Research engine'],['field-engine','Field engine']];for(const [id] of map)for(const e of PROTOCOL_ENGINES)$(id).add(new Option(e.icon+' '+e.name,e.id));setProtocolEngine('food');
 $('protocol-search').addEventListener('input',renderProtocolEngines);$('protocol-source-search').addEventListener('input',renderProtocolSources);$('protocol-engine-select').addEventListener('change',()=>setProtocolEngine($('protocol-engine-select').value));$('pr-engine').addEventListener('change',()=>{$('protocol-engine-select').value=$('pr-engine').value});
 $('protocol-results').addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.protocolResearch){setProtocolEngine(b.dataset.protocolResearch);route('protocol-research')}else if(b.dataset.protocolCreate){let e=PROTOCOL_BY_ID[b.dataset.protocolCreate];$('project-title').value=e.name+' · local pilot';$('project-domain').value=PROTOCOL_DOMAINS[e.id];$('project-need').value=e.problem.slice(0,2800);$('project-goal').value=e.metric[0][1]+' ('+e.metric[0][2]+'); define baseline and measurement method before deployment.';$('project-constraints').value=e.critical.slice(0,2200);route('projects');toast('Starter project populated. Add a real location, revise it and save before attaching fieldwork.')}});
 $('protocol-research-form').addEventListener('submit',generateProtocolResearch);$('pr-copy').addEventListener('click',()=>copyText($('pr-output').value));$('pr-export').addEventListener('click',()=>{if(!activeProtocolResearch)return toast('Generate a brief first.',true);down('empowerment_protocol_research_brief.txt',$('pr-output').value+'\n\nPROMPT CHAIN\n'+activeProtocolResearch.promptChain.join('\n\n---\n\n'),'text/plain;charset=utf-8')});$('pr-prompts').addEventListener('click',e=>{const n=e.target.closest('[data-prompt-copy]');if(n&&activeProtocolResearch)copyText(activeProtocolResearch.promptChain[Number(n.dataset.promptCopy)])});
 $('pm-type').addEventListener('change',renderProtocolModelInputs);$('pm-sensitivity').addEventListener('input',()=>say('pm-sens-label',$('pm-sensitivity').value));$('pm-form').addEventListener('submit',runProtocolModel);$('pm-reset').addEventListener('click',renderProtocolModelInputs);$('pm-export').addEventListener('click',()=>{if(!activeProtocolModel)return toast('Calculate a scenario first.',true);down('empowerment_scenario.json',JSON.stringify(activeProtocolModel,null,2))});renderProtocolModelInputs();
 $('field-project').addEventListener('change',renderFieldwork);$('field-start').addEventListener('click',startFieldwork);$('field-detail').addEventListener('change',e=>{let el=e.target.closest('[data-field-task]');if(!el)return;let w=S.fieldwork.find(w=>w.id===$('field-project').value);let t=w?.tasks[Number(el.dataset.fieldTask)];if(!t)return;t.done=el.checked;persist();renderFieldwork()});$('field-detail').addEventListener('click',e=>{if(e.target.id==='field-metadata-save')saveFieldMetadata()});$('field-detail').addEventListener('submit',e=>{if(e.target.id==='field-obs-form')saveObservation(e)});
 $('legacy-file').addEventListener('change',()=>{legacyCandidate=null;$('legacy-merge').disabled=true;say('legacy-report','File selected; preview and validate before merging.')});$('legacy-preview').addEventListener('click',previewLegacy);$('legacy-merge').addEventListener('click',mergeLegacy);$('merge-tests').addEventListener('click',runMergedTests);
}


window.FoundryBridge=Object.freeze({
 snapshot:()=>clone(S),dataset:()=>clone(EMBED),selectedProject:()=>selectedProject,
 blueprint:(extra=[])=>selected()?clone(blueprint({...selected(),methods:[...new Set([...selected().methods,...extra])]})):null,
 child:(extra=[])=>selected()?childSource({...selected(),methods:[...new Set([...selected().methods,...extra])]}):'',
 setActiveProject:(id)=>{if(!P(id))throw Error('Unknown project');selectedProject=id;invalidateOutput();renderProjectSelects();renderFoundryMethods();renderFoundryTech();drawGraph();window.dispatchEvent(new CustomEvent('foundry:state'));return id},
 importModulePack:(pack)=>{if(!pack||!Array.isArray(pack.modules)||!Array.isArray(pack.methods))throw Error('Invalid import pack');const next=clone(S);const incomingMethods=pack.methods.map(valMethod),incomingMods=valEcosystem({customModules:pack.modules,projectModules:{}}).customModules;const existingMethodIds=new Set([...EMBED.methods,...next.customMethods].map(m=>m.id)),existingModuleIds=new Set([...(window.FOUNDRY_REGISTRY?.modules||[]),...next.ecosystem.customModules].map(m=>m.id));let ma=0,mo=0;for(const m of incomingMethods){if(existingMethodIds.has(m.id))continue;if(next.customMethods.length>=100)throw Error('Method limit reached');next.customMethods.push(m);existingMethodIds.add(m.id);ma++}for(const mod of incomingMods){if(existingModuleIds.has(mod.id))continue;if(next.ecosystem.customModules.length>=50)throw Error('Module limit reached');next.ecosystem.customModules.push(mod);existingModuleIds.add(mod.id);mo++}for(const mod of next.ecosystem.customModules){if(mod.method_ids.some(id=>!existingMethodIds.has(id))||mod.dependencies.some(id=>!existingModuleIds.has(id)))throw Error('Missing method or module dependency for '+mod.id)}const verified=validateFull(next);S=verified;log('module_pack_import',`${mo} modules, ${ma} methods`);persist();refresh();return {modules_added:mo,methods_added:ma}},
 getModuleState:()=>clone(S.ecosystem),
 getInnovationState:()=>clone(S.innovation),
 setInnovationState:(next)=>{const valid=valInnovation(next);S.innovation=valid;log('innovation_updated','Inert project genome/experiment records');persist();return clone(S.innovation)},
 setModuleState:(next)=>{S.ecosystem=valEcosystem(next);log('ecosystem_updated','Declarative module data');persist();return clone(S.ecosystem)},
 open:(routeName)=>route(routeName),message:toast,
 readiness:()=>({storage:storageMode,project_count:S.projects.length,selected:selectedProject})
});
